TRUNCATE TABLE public.questions RESTART IDENTITY;

INSERT INTO public.questions (chapter, question_text, options, correct_answer) VALUES
-- ==========================================
-- BAB 1: Kepramukaan Dasar
-- ==========================================
(1, 'Siapakah penulis buku referensi Pramuka "Boyman"?', '["A. Agnes Baden-Powell","B. Lord Robert Baden Powell","C. Andri Bob Sunardi","D. Lord Edward Cecil"]', 'C. Andri Bob Sunardi'),
(1, 'Sifat kepramukaan yang penyelenggaraannya disesuaikan dengan keadaan dan kebutuhan masyarakat di negaranya adalah sifat...', '["A. Olympia Hall","B. Nasional","C. Pulau Brownsea","D. Kenya"]', 'B. Nasional'),
(1, 'Kepramukaan dapat berlaku untuk siapa saja dan diselenggarakan di mana saja. Ini disebut sifat...', '["A. Universal","B. Soenardjo Atmodipuro","C. Lord Edward Cecil","D. Mayor Kenneth McLaren"]', 'A. Universal'),
(1, 'Kepramukaan harus dapat mengembangkan rasa persaudaraan dan persahabatan antar sesama manusia. Ini adalah cerminan dari sifat...', '["A. 21 - 25 tahun","B. Internasional","C. 14 - 18 tahun","D. 17 - 25 tahun"]', 'B. Internasional'),
(1, 'Fungsi kepramukaan bagi peserta didik (anak/pemuda) pada dasarnya adalah sebagai...', '["A. Ramu, Rakit, Terap","B. Bantara, Laksana","C. Permainan yang menarik","D. Tunas Kelapa"]', 'C. Permainan yang menarik'),
(1, 'Bagi orang dewasa, kepramukaan bukan lagi permainan, melainkan suatu tugas yang memerlukan keikhlasan. Ini adalah fungsi sebagai...', '["A. Kepramukaan","B. Pengabdian","C. Pasukan","D. Perindukan"]', 'B. Pengabdian'),
(1, 'Kepramukaan berfungsi sebagai alat untuk memenuhi kebutuhan dan tujuan masyarakat. Ini adalah fungsi kepramukaan bagi...', '["A. Ransel (Carrier / Backpack)","B. Sleeping Bag (Kantong Tidur)","C. Flysheet","D. Masyarakat dan Organisasi"]', 'D. Masyarakat dan Organisasi'),
(1, 'Proses pendidikan di luar lingkungan sekolah dan keluarga dalam bentuk kegiatan menarik di alam terbuka disebut...', '["A. Tunas Kelapa","B. Kepramukaan","C. Pramuka Garuda","D. Nasional"]', 'B. Kepramukaan'),
(1, 'Orang-orang atau anggota yang mengikuti kegiatan dan tergabung di dalam organisasi kepanduan di Indonesia disebut...', '["A. Pramuka","B. Andri Bob Sunardi","C. Tunas Kelapa","D. TKU dan TKK"]', 'A. Pramuka'),
(1, 'Organisasi atau wadah resmi yang menyelenggarakan pendidikan kepramukaan di Indonesia adalah...', '["A. Kwartir","B. Ambalan","C. Gerakan Pramuka","D. Reka"]', 'C. Gerakan Pramuka'),
(1, 'Kepanjangan dari PRAMUKA adalah...', '["A. Praja Muda Karana","B. Andri Bob Sunardi","C. Tanda Kecakapan Umum","D. Rakyat muda yang suka berkarya"]', 'A. Praja Muda Karana'),
(1, 'Istilah Praja Muda Karana memiliki arti...', '["A. Beriman, bertakwa, dan berakhlak mulia","B. Rakyat muda yang suka berkarya","C. TKU dan TKK","D. 21 - 25 tahun"]', 'B. Rakyat muda yang suka berkarya'),
(1, 'Bapak Pramuka Indonesia adalah...', '["A. Agnes Baden-Powell","B. H. Mutahar","C. Sri Sultan Hamengkubuwono IX","D. W.R. Supratman"]', 'C. Sri Sultan Hamengkubuwono IX'),
(1, 'Bapak Pandu Dunia (Chief Scout of the World) adalah...', '["A. Lord Robert Baden Powell","B. H. Mutahar","C. Andri Bob Sunardi","D. Agnes Baden-Powell"]', 'A. Lord Robert Baden Powell'),
(1, 'Tujuan Gerakan Pramuka yang pertama adalah membentuk anggota pramuka agar memiliki kepribadian yang...', '["A. Tanda Kecakapan Khusus","B. Trisatya dan Dasadarma","C. Beriman, bertakwa, dan berakhlak mulia","D. Ing Ngarso Sung Tulodo"]', 'C. Beriman, bertakwa, dan berakhlak mulia'),
(1, 'Tujuan Gerakan Pramuka yang kedua adalah agar anggota pramuka menjadi warga negara yang...', '["A. Nyeri","B. Berjiwa Pancasila","C. Mafeking","D. Olympia Hall"]', 'B. Berjiwa Pancasila'),
(1, 'Salah satu pilar metode kepramukaan adalah "Learning by Doing", yang artinya...', '["A. Trisatya dan Dasadarma","B. Belajar sambil melakukan","C. 16 - 20 tahun","D. Pasukan"]', 'B. Belajar sambil melakukan'),
(1, 'Penggolongan usia Pramuka Siaga adalah...', '["A. 7 - 10 tahun","B. 21 - 25 tahun","C. 17 - 25 tahun","D. 11 - 15 tahun"]', 'A. 7 - 10 tahun'),
(1, 'Penggolongan usia Pramuka Penggalang adalah...', '["A. 17 - 25 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 14 - 18 tahun"]', 'B. 11 - 15 tahun'),
(1, 'Penggolongan usia Pramuka Penegak adalah...', '["A. 17 - 25 tahun","B. 14 - 18 tahun","C. 16 - 20 tahun","D. 7 - 10 tahun"]', 'C. 16 - 20 tahun'),
(1, 'Penggolongan usia Pramuka Pandega adalah...', '["A. 7 - 10 tahun","B. 17 - 25 tahun","C. 11 - 15 tahun","D. 21 - 25 tahun"]', 'D. 21 - 25 tahun'),
(1, 'Kode Kehormatan bagi Pramuka Siaga terdiri dari...', '["A. Ing Madyo Mangun Karso","B. Dwisatya dan Dwidarma","C. Tut Wuri Handayani","D. Trisatya dan Dasadarma"]', 'B. Dwisatya dan Dwidarma'),
(1, 'Kode Kehormatan bagi Pramuka Penggalang, Penegak, dan Pandega terdiri dari...', '["A. Tut Wuri Handayani","B. Trisatya dan Dasadarma","C. Ing Madyo Mangun Karso","D. Ikhlas Bakti Bina Bangsa"]', 'B. Trisatya dan Dasadarma'),
(1, 'Sistem Pendidikan Kepramukaan menggunakan Sistem Among yang digagas oleh...', '["A. Regu","B. 21 - 25 tahun","C. Ki Hajar Dewantara","D. Permainan yang menarik"]', 'C. Ki Hajar Dewantara'),
(1, 'Semboyan Sistem Among di depan memberikan teladan adalah...', '["A. Ing Ngarso Sung Tulodo","B. Dwisatya dan Dwidarma","C. Trisatya dan Dasadarma","D. Tut Wuri Handayani"]', 'A. Ing Ngarso Sung Tulodo'),
(1, 'Semboyan Sistem Among di tengah membangun kemauan adalah...', '["A. Dwisatya dan Dwidarma","B. Ing Madyo Mangun Karso","C. Trisatya dan Dasadarma","D. Good Turn (Berbuat Kebaikan)"]', 'B. Ing Madyo Mangun Karso'),
(1, 'Semboyan Sistem Among di belakang memberikan dorongan adalah...', '["A. Ikhlas Bakti Bina Bangsa","B. Satyaku Kudarmakan, Darmaku Kubaktikan","C. Tut Wuri Handayani","D. Ing Madyo Mangun Karso"]', 'C. Tut Wuri Handayani'),
(1, 'Satuan terkecil dalam Pramuka Siaga disebut...', '["A. Gugus Depan","B. Racana","C. Barung","D. Pasukan"]', 'C. Barung'),
(1, 'Satuan terkecil dalam Pramuka Penggalang disebut...', '["A. Gugus Depan","B. Regu","C. Ambalan","D. Barung"]', 'B. Regu'),
(1, 'Satuan terkecil dalam Pramuka Penegak disebut...', '["A. Kwartir","B. Racana","C. Ambalan","D. Sangga"]', 'D. Sangga'),
(1, 'Satuan terkecil dalam Pramuka Pandega disebut...', '["A. Reka","B. Sangga","C. Perindukan","D. Gugus Depan"]', 'A. Reka'),
(1, 'Kumpulan dari beberapa Barung dalam Siaga disebut...', '["A. Pasukan","B. Perindukan","C. Sangga","D. Racana"]', 'B. Perindukan'),
(1, 'Kumpulan dari beberapa Regu dalam Penggalang disebut...', '["A. Gugus Depan","B. Pasukan","C. Ambalan","D. Barung"]', 'B. Pasukan'),
(1, 'Kumpulan dari beberapa Sangga dalam Penegak disebut...', '["A. Ambalan","B. Sangga","C. Kwartir","D. Pasukan"]', 'A. Ambalan'),
(1, 'Wadah pembinaan Pramuka Pandega di Perguruan Tinggi disebut...', '["A. Gugus Depan","B. Racana","C. Sangga","D. Ambalan"]', 'B. Racana'),
(1, 'Tanda kecakapan dalam kepramukaan dibagi menjadi dua, yaitu...', '["A. TKU dan TKK","B. Tanda Kecakapan Umum","C. Sangga","D. 16 - 20 tahun"]', 'A. TKU dan TKK'),
(1, 'TKU singkatan dari...', '["A. Pramuka Garuda","B. Tanda Kecakapan Umum","C. Mula, Bantu, Tata","D. Purwa, Madya, Utama"]', 'B. Tanda Kecakapan Umum'),
(1, 'TKK singkatan dari...', '["A. Tanda Kecakapan Khusus","B. Purwa, Madya, Utama","C. Pramuka Garuda","D. Ramu, Rakit, Terap"]', 'A. Tanda Kecakapan Khusus'),
(1, 'Tingkatan TKU pada Pramuka Siaga adalah...', '["A. Ramu, Rakit, Terap","B. Mula, Bantu, Tata","C. Bantara, Laksana","D. Pramuka Garuda"]', 'B. Mula, Bantu, Tata'),
(1, 'Tingkatan TKU pada Pramuka Penggalang adalah...', '["A. Ramu, Rakit, Terap","B. Pramuka Garuda","C. Siaga, Penggalang, Penegak","D. Bantara, Laksana"]', 'A. Ramu, Rakit, Terap'),
(1, 'Tingkatan TKU pada Pramuka Penegak adalah...', '["A. Bantara, Laksana","B. Ramu, Rakit, Terap","C. Purwa, Madya, Utama","D. Mula, Bantu, Tata"]', 'A. Bantara, Laksana'),
(1, 'Tingkatan TKK (Tanda Kecakapan Khusus) dibagi menjadi 3 tingkatan, yaitu...', '["A. Pramuka Garuda","B. Siaga, Penggalang, Penegak","C. Purwa, Madya, Utama","D. Ramu, Rakit, Terap"]', 'C. Purwa, Madya, Utama'),
(1, 'Lambang Gerakan Pramuka Indonesia adalah...', '["A. Tunas Kelapa","B. Pasukan","C. Regu","D. Universal"]', 'A. Tunas Kelapa'),
(1, 'Pencipta lambang Tunas Kelapa adalah...', '["A. Samuel F.B. Morse","B. Soenardjo Atmodipuro","C. Lord Edward Cecil","D. H. Mutahar"]', 'B. Soenardjo Atmodipuro'),
(1, 'Bentuk lambang Pramuka Internasional (WOSM) adalah...', '["A. 14 Agustus 1961","B. Mula, Bantu, Tata","C. Bunga Lily (Fleur-de-lis)","D. Tanda Kecakapan Umum"]', 'C. Bunga Lily (Fleur-de-lis)'),
(1, 'Gerakan Pramuka resmi diperkenalkan kepada rakyat Indonesia pada tanggal...', '["A. 14 Agustus 1961","B. 14 Maret 1961","C. 14 Agustus 1962","D. 14 Februari 1961"]', 'A. 14 Agustus 1961'),
(1, 'Oleh karena itu, Hari Pramuka di Indonesia diperingati setiap tanggal...', '["A. 14 Agustus","B. 9 Agustus","C. 16 Agustus","D. 19 Agustus"]', 'A. 14 Agustus'),
(1, 'Undang-Undang yang mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. Ing Madyo Mangun Karso","B. UU No. 12 Tahun 2010","C. Lord Robert Baden Powell","D. Andri Bob Sunardi"]', 'B. UU No. 12 Tahun 2010'),
(1, 'Motto Gerakan Pramuka adalah...', '["A. Satyaku Kudarmakan, Darmaku Kubaktikan","B. Ikhlas Bakti Bina Bangsa","C. Be Prepared (Selalu Siap)","D. Dwisatya dan Dwidarma"]', 'A. Satyaku Kudarmakan, Darmaku Kubaktikan'),
(1, 'Tingkatan tertinggi dalam setiap golongan Pramuka yang telah memenuhi syarat pencapaian Garuda disebut...', '["A. Bantara, Laksana","B. Siaga, Penggalang, Penegak","C. Pramuka Garuda","D. Purwa, Madya, Utama"]', 'C. Pramuka Garuda'),

-- ==========================================
-- BAB 3: Biografi Baden Powell
-- ==========================================
(3, 'Nama lengkap Bapak Pandu Dunia adalah...', '["A. Robert Stephenson Smyth Baden-Powell","B. Soenardjo Atmodipuro","C. Sri Sultan Hamengkubuwono IX","D. Rudyard Kipling"]', 'A. Robert Stephenson Smyth Baden-Powell'),
(3, 'Baden-Powell lahir di kota...', '["A. Gilwell Park","B. Kenya","C. London","D. Afrika Selatan"]', 'C. London'),
(3, 'Tanggal lahir Baden-Powell adalah...', '["A. 24 Februari 1857","B. 22 Februari 1857","C. 20 Februari 1857","D. 20 Februari 1857"]', 'B. 22 Februari 1857'),
(3, 'Nama ayah Baden-Powell adalah...', '["A. Prof. Domine Baden-Powell","B. W.R. Supratman","C. Andri Bob Sunardi","D. Rudyard Kipling"]', 'A. Prof. Domine Baden-Powell'),
(3, 'Profesi ayah Baden-Powell adalah seorang...', '["A. World Organization of the Scout Movement","B. Guru Besar Geometri di Universitas Oxford","C. Olave St. Clair Soames","D. Kapak menancap di balok kayu"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(3, 'Nama ibu dari Baden-Powell adalah...', '["A. Samuel F.B. Morse","B. W.R. Supratman","C. Miss Henrietta Grace Smyth","D. Rudyard Kipling"]', 'C. Miss Henrietta Grace Smyth'),
(3, 'Ayah dari ibu Baden-Powell (kakek dari pihak ibu) adalah seorang laksamana bernama...', '["A. Admiral William T. Smyth","B. Lord Edward Cecil","C. Ki Hajar Dewantara","D. W.R. Supratman"]', 'A. Admiral William T. Smyth'),
(3, 'Ayah Baden-Powell meninggal dunia ketika Baden-Powell berusia...', '["A. 3 tahun","B. 8 tahun","C. 6 tahun","D. 6 tahun"]', 'A. 3 tahun'),
(3, 'Julukan Baden-Powell saat bersekolah di Charterhouse School karena kebiasaannya mandi air dingin adalah...', '["A. London","B. Bathing Towel","C. 22 Februari 1857","D. Rovering to Success"]', 'B. Bathing Towel'),
(3, 'Kepala sekolah di Charterhouse yang sangat berpengaruh terhadap pembentukan karakter Baden-Powell adalah...', '["A. Dr. Haig Brown","B. Admiral William T. Smyth","C. Prof. Domine Baden-Powell","D. London"]', 'A. Dr. Haig Brown'),
(3, 'Setelah lulus dari Charterhouse, Baden-Powell mengikuti ujian militer dan lulus kavaleri dengan urutan ke...', '["A. 1899","B. Dua","C. Rudyard Kipling","D. Mayor Kenneth McLaren"]', 'B. Dua'),
(3, 'Pasukan kavaleri yang pertama kali ditempati Baden-Powell di India adalah...', '["A. Olympia Hall","B. Mafeking","C. 13th Hussars","D. London"]', 'C. 13th Hussars'),
(3, 'Baden-Powell pertama kali ditugaskan ke India sebagai prajurit muda pada tahun...', '["A. 1876","B. 1877","C. 1873","D. 1881"]', 'A. 1876'),
(3, 'Pangkat pertama Baden-Powell saat bergabung di ketentaraan di India adalah...', '["A. Bathing Towel","B. Letnan Jenderal","C. Pembantu Letnan (Sub-Lieutenant)","D. 1929"]', 'C. Pembantu Letnan (Sub-Lieutenant)'),
(3, 'Suku Zulu, Ashanti, dan Matabele di Afrika memberikan julukan khusus kepada Baden-Powell, yaitu...', '["A. Raja Edward VII","B. Impeesa","C. Bathing Towel","D. Pembantu Letnan (Sub-Lieutenant)"]', 'B. Impeesa'),
(3, 'Arti dari julukan "Impeesa" yang diberikan oleh suku di Afrika adalah...', '["A. 22 Februari 1857","B. 8 Januari 1941","C. Serigala yang tidak pernah tidur","D. World Organization of the Scout Movement"]', 'C. Serigala yang tidak pernah tidur'),
(3, 'Baden-Powell berhasil mempertahankan sebuah kota dari kepungan bangsa Boer di Afrika Selatan selama 217 hari. Kota tersebut bernama...', '["A. H. Mutahar","B. Rudyard Kipling","C. Sri Sultan Hamengkubuwono IX","D. Mafeking"]', 'D. Mafeking'),
(3, 'Peristiwa pengepungan kota Mafeking terjadi pada tahun...', '["A. London","B. 1899 - 1900","C. Nyeri","D. Gilwell Park"]', 'B. 1899 - 1900'),
(3, 'Buku panduan pelacakan militer yang ditulis Baden-Powell dan kelak disukai oleh anak-anak muda Inggris adalah...', '["A. Boyman","B. Aids to Scouting","C. The Jungle Book","D. Rovering to Success"]', 'B. Aids to Scouting'),
(3, 'Buku "Aids to Scouting" diterbitkan pada tahun...', '["A. 1899","B. 1904","C. 1894","D. 1903"]', 'A. 1899'),
(3, 'Perkemahan percobaan kepanduan pertama kali diadakan oleh Baden-Powell di sebuah pulau bernama...', '["A. Mayor Kenneth McLaren","B. Pulau Brownsea","C. Agnes Baden-Powell","D. W.R. Supratman"]', 'B. Pulau Brownsea'),
(3, 'Perkemahan di Pulau Brownsea yang menjadi tonggak sejarah kepramukaan dilaksanakan pada tahun...', '["A. 1909","B. 1907","C. 1903","D. 1911"]', 'B. 1907'),
(3, 'Berapa jumlah anak laki-laki yang mengikuti perkemahan percobaan di Pulau Brownsea?', '["A. 23 anak","B. 24 anak","C. 22 anak","D. 20 anak"]', 'C. 22 anak'),
(3, 'Teman tentara yang membantu Baden-Powell mengurus perkemahan di Pulau Brownsea adalah...', '["A. Mayor Kenneth McLaren","B. Mafeking","C. Afrika Selatan","D. Nyeri"]', 'A. Mayor Kenneth McLaren'),
(3, 'Buku panduan utama yang menjadi cikal bakal berdirinya gerakan kepanduan dunia adalah...', '["A. Rovering to Success","B. The Jungle Book","C. Scouting for Boys","D. Aids to Scouting"]', 'C. Scouting for Boys'),
(3, 'Buku "Scouting for Boys" karya Baden-Powell pertama kali diterbitkan pada tahun...', '["A. 1910","B. 1908","C. 1912","D. 1910"]', 'B. 1908'),
(3, 'Organisasi kepanduan putri (Girl Guides) pertama kali dibentuk dengan bantuan adik perempuan Baden-Powell yang bernama...', '["A. Andri Bob Sunardi","B. Ki Hajar Dewantara","C. Agnes Baden-Powell","D. Rudyard Kipling"]', 'C. Agnes Baden-Powell'),
(3, 'Organisasi Girl Guides (Kepanduan Putri) dirintis pada tahun...', '["A. 1909","B. 1910","C. 1906","D. 1913"]', 'B. 1910'),
(3, 'Kepanduan untuk golongan anak-anak (Siaga/Wolf Cub) didirikan oleh Baden-Powell pada tahun...', '["A. 1915","B. 1918","C. 1916","D. 1921"]', 'C. 1916'),
(3, 'Buku panduan yang digunakan Baden-Powell untuk menginspirasi golongan Siaga (Wolf Cub) adalah...', '["A. Scouting for Boys","B. The Jungle Book","C. Boyman","D. Aids to Scouting"]', 'B. The Jungle Book'),
(3, 'Penulis buku "The Jungle Book" yang menginspirasi pembentukan golongan Siaga adalah...', '["A. Rudyard Kipling","B. Aids to Scouting","C. Scouting for Boys","D. Rovering to Success"]', 'A. Rudyard Kipling'),
(3, 'Kepanduan untuk golongan pemuda (Penegak/Rover Scout) dibentuk pada tahun...', '["A. 1917","B. 1918","C. 1922","D. 1921"]', 'B. 1918'),
(3, 'Buku panduan untuk Rover Scout yang ditulis oleh Baden-Powell pada tahun 1922 berjudul...', '["A. The Jungle Book","B. Scouting for Boys","C. Rovering to Success","D. Aids to Scouting"]', 'C. Rovering to Success'),
(3, 'Jambore Kepanduan Dunia pertama kali diadakan di gedung...', '["A. Olympia Hall","B. Impeesa","C. Pulau Brownsea","D. The Jungle Book"]', 'A. Olympia Hall'),
(3, 'Jambore Dunia pertama diadakan di kota London pada tahun...', '["A. 1922","B. 1920","C. 1918","D. 1922"]', 'B. 1920'),
(3, 'Pada malam terakhir Jambore Dunia pertama, Baden-Powell secara resmi diangkat menjadi...', '["A. Guru Besar Geometri di Universitas Oxford","B. World Organization of the Scout Movement","C. Bapak Pandu Dunia (Chief Scout of the World)","D. Nyeri"]', 'C. Bapak Pandu Dunia (Chief Scout of the World)'),
(3, 'Gelar kehormatan "Lord" (Baron) dianugerahkan kepada Baden-Powell oleh Raja George V pada tahun...', '["A. 1930","B. 1933","C. 1929","D. 1924"]', 'C. 1929'),
(3, 'Nama istri Baden-Powell yang kelak menjadi Chief Guide of the World adalah...', '["A. Sri Sultan Hamengkubuwono IX","B. Olave St. Clair Soames","C. Ki Hajar Dewantara","D. Samuel F.B. Morse"]', 'B. Olave St. Clair Soames'),
(3, 'Baden-Powell pensiun dari dinas kemiliteran Inggris dengan pangkat terakhir...', '["A. 1920","B. Letnan Jenderal","C. Dinizulu","D. Aids to Scouting"]', 'B. Letnan Jenderal'),
(3, 'Raja Inggris yang menyarankan Baden-Powell untuk pensiun dari militer agar bisa membesarkan Gerakan Kepanduan adalah...', '["A. 22 Februari 1857","B. Rudyard Kipling","C. Raja Edward VII","D. Kenya"]', 'C. Raja Edward VII'),
(3, 'Pada tahun 1919, W. de Bois Maclaren menyumbangkan sebidang tanah untuk pusat pelatihan pembina pramuka yang diberi nama...', '["A. Mayor Kenneth McLaren","B. H. Mutahar","C. Gilwell Park","D. Rudyard Kipling"]', 'C. Gilwell Park'),
(3, 'Kursus Pembina Pramuka (Wood Badge) pertama kali diselenggarakan di Gilwell Park pada tahun...', '["A. 1921","B. 1919","C. 1923","D. 1916"]', 'B. 1919'),
(3, 'Kalung manik-manik kayu (Wood Badge) berasal dari kalung pimpinan suku Afrika yang pernah dikalahkan oleh Baden-Powell, bernama...', '["A. Rudyard Kipling","B. Dinizulu","C. Olave St. Clair Soames","D. Sri Sultan Hamengkubuwono IX"]', 'B. Dinizulu'),
(3, 'Simbol dari pusat pelatihan pembina Gilwell Park adalah...', '["A. Raja Edward VII","B. 1899 - 1900","C. Kapak menancap di balok kayu","D. Rovering to Success"]', 'C. Kapak menancap di balok kayu'),
(3, 'Baden-Powell menghabiskan masa tuanya dan meninggal dunia di negara...', '["A. Afrika Selatan","B. Pulau Brownsea","C. London","D. Kenya"]', 'D. Kenya'),
(3, 'Baden-Powell meninggal dunia pada tanggal...', '["A. 8 Januari 1941","B. 8 Januari 1942","C. 6 Januari 1941","D. 6 Januari 1941"]', 'A. 8 Januari 1941'),
(3, 'Baden-Powell dimakamkan di pemakaman St. Peter, di kota...', '["A. Pulau Brownsea","B. Afrika Selatan","C. Nyeri","D. Kenya"]', 'C. Nyeri'),
(3, 'Usia Baden-Powell saat meninggal dunia adalah...', '["A. 82 tahun","B. 82 tahun","C. 83 tahun","D. 84 tahun"]', 'C. 83 tahun'),
(3, 'Pada batu nisan makam Baden-Powell terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti...', '["A. Saya telah pulang","B. Rudyard Kipling","C. 1907","D. Scouting for Boys"]', 'A. Saya telah pulang'),
(3, 'Organisasi kepanduan dunia saat ini bernaung di bawah organisasi bernama WOSM, singkatan dari...', '["A. Samuel F.B. Morse","B. World Organization of the Scout Movement","C. Lord Robert Baden Powell","D. Olave St. Clair Soames"]', 'B. World Organization of the Scout Movement'),

-- ==========================================
-- BAB 5: Scouting for Boys
-- ==========================================
(5, 'Bab 5 dalam buku referensi Boyman secara khusus membahas rangkuman dari buku legendaris karya Baden-Powell yang berjudul...', '["A. The Jungle Book","B. Scouting for Boys","C. Boyman","D. Rovering to Success"]', 'B. Scouting for Boys'),
(5, 'Buku Scouting for Boys pada dasarnya dibagi ke dalam beberapa sub-bab yang disebut dengan istilah...', '["A. Scouting for Boys","B. The Jungle Book","C. Cerita Api Unggun","D. Boyman"]', 'C. Cerita Api Unggun'),
(5, 'Ada berapa total Cerita Api Unggun (Campfire Yarns) yang menjadi susunan utama materi Scouting for Boys?', '["A. 31 Cerita","B. 21 Cerita","C. 24 Cerita","D. 26 Cerita"]', 'D. 26 Cerita'),
(5, 'Cerita Api Unggun ke-1 membahas sejarah tentang pasukan anak laki-laki di Afrika yang menjadi inspirasi kepanduan, yang disebut...', '["A. Mafeking Cadet Corps","B. Mencari dan Mengikuti Jejak (Tracking)","C. Sherlock Holmes","D. Kewarganegaraan (Citizenship)"]', 'A. Mafeking Cadet Corps'),
(5, 'Pemimpin pasukan anak-anak pada masa pengepungan Mafeking tersebut adalah...', '["A. Sistem Regu (Patrol System)","B. Lord Edward Cecil","C. Be Prepared (Selalu Siap)","D. Mafeking Cadet Corps"]', 'B. Lord Edward Cecil'),
(5, 'Baden-Powell menyadari kehebatan pasukan anak-anak di Mafeking yang kemudian menjadi cikal bakal pentingnya peran kaum muda. Pengepungan kota Mafeking terjadi di negara...', '["A. Afrika Selatan","B. Kenya","C. Olympia Hall","D. Nyeri"]', 'A. Afrika Selatan'),
(5, 'Cerita Api Unggun ke-4 membahas inti dari sistem kepramukaan yang membagi anggota ke dalam kelompok kecil, disebut dengan...', '["A. Good Turn (Berbuat Kebaikan)","B. Tetap tenang dan tidak panik","C. Sistem Regu (Patrol System)","D. Perkemahan (Camping)"]', 'C. Sistem Regu (Patrol System)'),
(5, 'Menurut gagasan awal Baden-Powell, jumlah anggota yang ideal dalam satu regu pramuka (patrol) adalah...', '["A. Raja Arthur","B. 6 sampai 8 orang","C. Survival (Bertahan Hidup)","D. Afrika Selatan"]', 'B. 6 sampai 8 orang'),
(5, 'Sebutan untuk pemimpin regu dalam bahasa Inggris yang dicetuskan oleh Baden-Powell adalah...', '["A. Perkemahan (Camping)","B. Pionering / Kepeloporan","C. Ikatan Palang (Square Lashing)","D. Patrol Leader"]', 'D. Patrol Leader'),
(5, 'Cerita Api Unggun ke-8 membahas tentang keterampilan membuat bangunan darurat menggunakan kayu dan tali, yang dalam istilah kepramukaan disebut...', '["A. Pionering / Kepeloporan","B. Kesehatan fisik dan kebugaran tubuh","C. Binatang dan Tumbuh-tumbuhan","D. Lord Edward Cecil"]', 'A. Pionering / Kepeloporan'),
(5, 'Simpul dasar dalam pionering yang berguna untuk menyambung dua utas tali yang sama besar dan tidak licin adalah...', '["A. Simpul Mati (Reef Knot)","B. Simpul Pangkal (Clove Hitch)","C. Simpul Anyam (Sheet Bend)","D. Ikatan Palang (Square Lashing)"]', 'A. Simpul Mati (Reef Knot)'),
(5, 'Simpul yang berguna untuk mengikat leher binatang agar tidak tercekik, serta sering menjadi simpul dasar penyelamatan adalah...', '["A. Ikatan Palang (Square Lashing)","B. Simpul Delapan","C. Simpul Tiang (Bowline)","D. Simpul Anyam (Sheet Bend)"]', 'C. Simpul Tiang (Bowline)'),
(5, 'Simpul yang paling sering digunakan untuk memulai dan mengakhiri sebuah ikatan pada tongkat pionering adalah...', '["A. Ikatan Palang (Square Lashing)","B. Simpul Pangkal (Clove Hitch)","C. Simpul Tiang (Bowline)","D. Simpul Anyam (Sheet Bend)"]', 'B. Simpul Pangkal (Clove Hitch)'),
(5, 'Simpul yang digunakan untuk menyambung dua utas tali yang ukurannya tidak sama besar dan dalam keadaan kering adalah...', '["A. Ikatan Silang","B. Simpul Pangkal (Clove Hitch)","C. Simpul Tiang (Bowline)","D. Simpul Anyam (Sheet Bend)"]', 'D. Simpul Anyam (Sheet Bend)'),
(5, 'Ikatan yang digunakan untuk menggabungkan dua buah tongkat yang bersilangan tegak lurus (membentuk sudut 90 derajat) adalah...', '["A. Ikatan Palang (Square Lashing)","B. Simpul Mati (Reef Knot)","C. Ikatan Silang","D. Simpul Anyam (Sheet Bend)"]', 'A. Ikatan Palang (Square Lashing)'),
(5, 'Cerita Api Unggun ke-9 membahas mengenai kehidupan di alam terbuka, yaitu rutinitas...', '["A. Hidung, bukan mulut","B. Perkemahan (Camping)","C. Be Prepared (Selalu Siap)","D. Binatang dan Tumbuh-tumbuhan"]', 'B. Perkemahan (Camping)'),
(5, 'Hal yang paling utama dan penting untuk diperhatikan saat memilih lokasi untuk mendirikan tenda perkemahan adalah...', '["A. Tenda Prisma","B. Ransel (Carrier / Backpack)","C. Dekat sumber air bersih dan aman dari bahaya alam","D. Sleeping Bag (Kantong Tidur)"]', 'C. Dekat sumber air bersih dan aman dari bahaya alam'),
(5, 'Cerita Api Unggun ke-10 memberikan panduan teknis yang sangat dibutuhkan regu mandiri, yaitu tentang...', '["A. Masakan di Perkemahan (Camp Cooking)","B. Kesehatan fisik dan kebugaran tubuh","C. Simpul Tiang (Bowline)","D. Simpul Pangkal (Clove Hitch)"]', 'A. Masakan di Perkemahan (Camp Cooking)'),
(5, 'Salah satu makanan khas perkemahan ala Baden-Powell, di mana adonan tepung dililitkan pada sebatang kayu lalu dipanggang di atas bara api, disebut...', '["A. Good Turn (Berbuat Kebaikan)","B. Roti Lilit (Twist)","C. Diare dan Disentri","D. Pionering / Kepeloporan"]', 'B. Roti Lilit (Twist)'),
(5, 'Cerita Api Unggun ke-11 dan 12 mengajarkan keterampilan mengasah kepekaan mata di alam terbuka, berupa...', '["A. 6 sampai 8 orang","B. Survival (Bertahan Hidup)","C. Mencari dan Mengikuti Jejak (Tracking)","D. Be Prepared (Selalu Siap)"]', 'C. Mencari dan Mengikuti Jejak (Tracking)'),
(5, 'Saat sedang mengikuti jejak di alam bebas, seorang Pramuka dianjurkan untuk berjalan dengan cara...', '["A. Mencari dan Mengikuti Jejak (Tracking)","B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","C. Kesehatan fisik dan kebugaran tubuh","D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya"]', 'D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya'),
(5, 'Dalam sandi jejak Pramuka, susunan batu yang ditumpuk menjadi tiga bagian dan ditambahkan satu batu kecil di sebelah kanan memiliki arti...', '["A. Jalan ke arah kanan","B. Simpul Mati (Reef Knot)","C. Perkemahan (Camping)","D. Menolong orang lain di setiap kesempatan"]', 'A. Jalan ke arah kanan'),
(5, 'Sebuah lingkaran yang digambar di tanah dengan titik di tengahnya merupakan tanda jejak kepanduan yang berarti...', '["A. Kesehatan fisik dan kebugaran tubuh","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Saya telah pulang / Kembali ke perkemahan","D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia"]', 'C. Saya telah pulang / Kembali ke perkemahan'),
(5, 'Cerita Api Unggun ke-13 menuntut seorang pandu untuk memiliki kemampuan observasi dan deduksi. Tokoh detektif fiksi yang sering dijadikan contoh oleh Baden-Powell untuk hal ini adalah...', '["A. Agnes Baden-Powell","B. Sherlock Holmes","C. W.R. Supratman","D. Ki Hajar Dewantara"]', 'B. Sherlock Holmes'),
(5, 'Cerita Api Unggun ke-14 berjudul "Menyembunyikan Diri - Mengendap" (Stalking). Mengendap sangat berguna di alam bebas untuk...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","C. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan","D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna"]', 'A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut'),
(5, 'Aturan utama yang harus diperhatikan seorang Pramuka saat sedang mengendap mendekati target di alam liar adalah...', '["A. Ikatan Palang (Square Lashing)","B. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","C. Bergerak berlawanan arah dengan hembusan angin","D. Jalan ke arah kanan"]', 'C. Bergerak berlawanan arah dengan hembusan angin'),
(5, 'Cerita Api Unggun ke-15 dan 16 membahas apresiasi terhadap lingkungan hidup, yakni tentang pengetahuan...', '["A. Kewarganegaraan (Citizenship)","B. Binatang dan Tumbuh-tumbuhan","C. Pionering / Kepeloporan","D. Cerita Api Unggun"]', 'B. Binatang dan Tumbuh-tumbuhan'),
(5, 'Prinsip konservasi dalam kepanduan menyatakan bahwa seorang Pramuka dilarang keras membunuh binatang apa pun, KECUALI...', '["A. Ikhlas Bakti Bina Bangsa","B. Good Turn (Berbuat Kebaikan)","C. Trisatya dan Dasadarma","D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan"]', 'D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan'),
(5, 'Pengetahuan seorang Pramuka dalam mengenali berbagai jenis pohon liar, dedaunan, dan akar yang bisa dimakan sangat menunjang kemampuannya dalam bidang...', '["A. Survival (Bertahan Hidup)","B. Sherlock Holmes","C. 23 April","D. Santo George (St. George)"]', 'A. Survival (Bertahan Hidup)'),
(5, 'Cerita Api Unggun ke-17 berjudul "Bagaimana Supaya Kuat", yang memberikan instruksi agar kaum muda terbiasa menjaga...', '["A. Bergerak berlawanan arah dengan hembusan angin","B. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya","C. Kesehatan fisik dan kebugaran tubuh","D. Be Prepared (Selalu Siap)"]', 'C. Kesehatan fisik dan kebugaran tubuh'),
(5, 'Untuk melatih kebugaran tubuh setiap hari, Baden-Powell menyarankan rutinitas senam pagi yang dikenal sebagai...', '["A. Kesehatan fisik dan kebugaran tubuh","B. 6 Latihan Fisik BP (BP Exercises)","C. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","D. Ikatan Palang (Square Lashing)"]', 'B. 6 Latihan Fisik BP (BP Exercises)'),
(5, 'Cerita Api Unggun ke-18 dan 19 mengulas tentang kebiasaan yang menyehatkan serta pencegahan penyakit. Baden-Powell sangat mewajibkan pandu bernapas dengan benar melalui...', '["A. Hidung, bukan mulut","B. Mencari dan Mengikuti Jejak (Tracking)","C. Simpul Tiang (Bowline)","D. Patrol Leader"]', 'A. Hidung, bukan mulut'),
(5, 'Penyakit yang sering menyerang anggota perkemahan akibat meminum air mentah atau lingkungan perkemahan yang kurang bersih (sanitasi buruk) adalah...', '["A. Survival (Bertahan Hidup)","B. Sherlock Holmes","C. Simpul Pangkal (Clove Hitch)","D. Diare dan Disentri"]', 'D. Diare dan Disentri'),
(5, 'Cerita Api Unggun ke-20 bertemakan "Sikap Kesatria" (Chivalry). Inspirasi utama Baden-Powell dalam membentuk karakter Pramuka ini berasal dari legenda pahlawan kuno, yaitu...', '["A. Menolong orang lain di setiap kesempatan","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","D. 6 Latihan Fisik BP (BP Exercises)"]', 'B. Kesatria Meja Bundar (Knights of the Round Table)'),
(5, 'Raja legendaris Inggris yang memimpin para kesatria mulia dalam perumpamaan Baden-Powell tersebut adalah...', '["A. Binatang dan Tumbuh-tumbuhan","B. Scouting for Boys","C. Raja Arthur","D. Kewarganegaraan (Citizenship)"]', 'C. Raja Arthur'),
(5, 'Tokoh orang suci pelindung Inggris (Patron Saint) yang juga dijadikan sebagai pelindung simbolis kaum pandu di seluruh dunia karena keberaniannya membunuh naga adalah...', '["A. Santo George (St. George)","B. W.R. Supratman","C. Mayor Kenneth McLaren","D. Andri Bob Sunardi"]', 'A. Santo George (St. George)'),
(5, 'Hari peringatan St. George, yang sering dirayakan secara internasional oleh anggota Pramuka sebagai ajang pembaruan Janji Pramuka, jatuh pada tanggal...', '["A. 25 April","B. 23 April","C. 21 April","D. 24 April"]', 'B. 23 April'),
(5, 'Cerita Api Unggun ke-21 menekankan pada konsep utama watak yang membuat seorang pandu dihormati, yaitu...', '["A. Lord Edward Cecil","B. 26 Cerita","C. Disiplin","D. Raja Arthur"]', 'C. Disiplin'),
(5, 'Ciri sejati dari kedisiplinan seorang Pramuka saat menerima instruksi dari pimpinannya adalah...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Saya telah pulang / Kembali ke perkemahan","C. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya"]', 'A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh'),
(5, 'Cerita Api Unggun ke-22 berjudul "Memperbaiki Diri". Hal ini mengajarkan filosofi bahwa seorang pandu sejati harus...', '["A. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","B. Melakukan tekanan langsung pada area luka / balut tekan","C. Dekat sumber air bersih dan aman dari bahaya alam","D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna"]', 'D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna'),
(5, 'Cerita Api Unggun ke-23 dan 24 membahas tentang keterampilan vital yang harus dimiliki setiap Pramuka jika terjadi insiden darurat, yakni tentang...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","C. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan","D. Simpul Anyam (Sheet Bend)"]', 'B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)'),
(5, 'Kaidah terpenting dan pertama kali yang harus dikuasai secara mental saat seorang Pramuka menghadapi situasi kecelakaan parah adalah...', '["A. Tetap tenang dan tidak panik","B. Simpul Pangkal (Clove Hitch)","C. Mafeking Cadet Corps","D. Hidung, bukan mulut"]', 'A. Tetap tenang dan tidak panik'),
(5, 'Apabila menemui korban yang mengalami pendarahan hebat (luka terbuka memancar), tindakan Pertolongan Pertama yang paling efektif dilakukan adalah...', '["A. Kesatria Meja Bundar (Knights of the Round Table)","B. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","C. Melakukan tekanan langsung pada area luka / balut tekan","D. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut"]', 'C. Melakukan tekanan langsung pada area luka / balut tekan'),
(5, 'Jika pakaian yang dikenakan oleh seseorang tiba-tiba tersambar api dan terbakar, tindakan penyelematan yang paling tepat diinstruksikan oleh Pramuka adalah...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","C. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna","D. Dekat sumber air bersih dan aman dari bahaya alam"]', 'B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal'),
(5, 'Cerita Api Unggun ke-25 mengingatkan tentang tujuan mulia kehadiran gerakan Pramuka dalam masyarakat, yaitu kewajiban untuk...', '["A. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","B. 6 sampai 8 orang","C. Bergerak berlawanan arah dengan hembusan angin","D. Menolong orang lain di setiap kesempatan"]', 'D. Menolong orang lain di setiap kesempatan'),
(5, 'Sebuah tradisi pandu yang diajarkan oleh Baden-Powell untuk melakukan setidaknya satu kebaikan kecil setiap harinya tanpa mengharap imbalan disebut dengan istilah...', '["A. Good Turn (Berbuat Kebaikan)","B. Roti Lilit (Twist)","C. Diare dan Disentri","D. Masakan di Perkemahan (Camp Cooking)"]', 'A. Good Turn (Berbuat Kebaikan)'),
(5, 'Cerita Api Unggun ke-26, yang menjadi bab pamungkas dalam materi buku Scouting for Boys, secara umum membahas tentang sikap tanggung jawab bermasyarakat, yakni...', '["A. Scouting for Boys","B. Kewarganegaraan (Citizenship)","C. Aids to Scouting","D. The Jungle Book"]', 'B. Kewarganegaraan (Citizenship)'),
(5, 'Inti dari jiwa kewarganegaraan seorang Pramuka adalah kemauannya untuk memahami sejarah, pemerintahan, dan hukum bangsanya, agar kelak ia menjadi...', '["A. Gilwell Park","B. Olympia Hall","C. Warga negara yang aktif dan bermanfaat bagi negaranya","D. Afrika Selatan"]', 'C. Warga negara yang aktif dan bermanfaat bagi negaranya'),
(5, 'Semboyan kepanduan utama yang diperkenalkan Baden-Powell dalam buku ini, yang wajib dipraktikkan baik dalam kesiapan fisik maupun mental oleh pandu di seluruh dunia adalah...', '["A. Be Prepared (Selalu Siap)","B. Ki Hajar Dewantara","C. W.R. Supratman","D. Samuel F.B. Morse"]', 'A. Be Prepared (Selalu Siap)'),
(5, 'Pesan moral secara keseluruhan dari Scouting for Boys yang tercantum di Bab 5 Boyman adalah membentuk remaja agar tidak hanya menjadi sosok petualang alam bebas, tetapi juga menjadi...', '["A. Dekat sumber air bersih dan aman dari bahaya alam","B. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","C. Saya telah pulang / Kembali ke perkemahan","D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia"]', 'D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia'),

-- ==========================================
-- BAB 9: Berkemah / Alam Bebas
-- ==========================================
(9, 'Pengertian berkemah dalam kepramukaan pada dasarnya adalah...', '["A. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","C. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","D. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang"]', 'B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung'),
(9, 'Salah satu sasaran dan motivasi utama dari kegiatan berkemah bagi anggota Pramuka adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","D. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat"]', 'A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka'),
(9, 'Tahap pertama yang mutlak harus dilakukan sebelum menyelenggarakan kegiatan perkemahan adalah...', '["A. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","C. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","D. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak"]', 'B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)'),
(9, 'Syarat utama tapak kemah (lokasi perkemahan) yang baik dan aman adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","D. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya"]', 'B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam'),
(9, 'Mengapa mendirikan tenda di dasar cekungan (lembah sempit) sangat dilarang dalam aturan perkemahan?', '["A. Matras","B. Groundsheet / Terpal","C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","D. Ponco"]', 'C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air'),
(9, 'Mendirikan tenda di bawah pohon tua yang sudah lapuk sangat dihindari karena...', '["A. Flysheet","B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","C. Survival Kit","D. Ponco"]', 'B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang'),
(9, 'Arah pintu tenda yang ideal saat didirikan di alam bebas sebaiknya...', '["A. Tenda Prisma","B. Membelakangi atau menyamping dari arah hembusan angin utama","C. Matras","D. Ponco"]', 'B. Membelakangi atau menyamping dari arah hembusan angin utama'),
(9, 'Tujuan utama membuat parit kecil di sekeliling tenda saat berkemah adalah...', '["A. Ransel (Carrier / Backpack)","B. Matras","C. Mencegah air hujan masuk/menggenangi bagian dalam tenda","D. Ponco"]', 'C. Mencegah air hujan masuk/menggenangi bagian dalam tenda'),
(9, 'Tenda darurat sementara yang dibuat dari bahan alam atau jas hujan (ponco) dinamakan...', '["A. Bivak","B. Lord Edward Cecil","C. Soenardjo Atmodipuro","D. Andri Bob Sunardi"]', 'A. Bivak'),
(9, 'Tenda standar beregu yang sering digunakan oleh Pramuka Penggalang, bentuknya seperti rumah dengan atap segitiga disebut...', '["A. Survival Kit","B. Matras","C. Tenda Prisma (Tenda Regu)","D. Nesting"]', 'C. Tenda Prisma (Tenda Regu)'),
(9, 'Agar patok (pasak) tenda menancap kuat menahan tarikan tali, kemiringan pasak yang ditancapkan ke tanah sebaiknya bersudut...', '["A. Flysheet","B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Ponco","D. Tenda Prisma"]', 'B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(9, 'Simpul yang paling tepat digunakan untuk mengikatkan tali tenda pada pasak agar mudah dikencangkan dan dikendurkan adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Delapan","C. Simpul Mati (Reef Knot)","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'D. Simpul Tali Tenda (Taut-line Hitch)'),
(9, 'Perlengkapan perkemahan dibagi menjadi dua macam, yaitu...', '["A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","B. Groundsheet / Terpal","C. Tenda Prisma","D. Matras"]', 'A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Pribadi saat berkemah adalah...', '["A. Nesting","B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","C. Survival Kit","D. Sleeping Bag (Kantong Tidur)"]', 'B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Regu adalah...', '["A. Ransel (Carrier / Backpack)","B. Matras","C. Tenda, alat masak regu (nesting), dan kotak P3K regu","D. Groundsheet / Terpal"]', 'C. Tenda, alat masak regu (nesting), dan kotak P3K regu'),
(9, 'Alat pelindung tubuh dari suhu dingin saat tidur di dalam tenda yang bentuknya seperti kepompong disebut...', '["A. Survival Kit","B. Sleeping Bag (Kantong Tidur)","C. Ransel (Carrier / Backpack)","D. Matras"]', 'B. Sleeping Bag (Kantong Tidur)'),
(9, 'Alat berupa alas tidur berbahan busa/spons yang berfungsi menahan hawa dingin dari tanah agar tidak langsung mengenai tubuh disebut...', '["A. Ransel (Carrier / Backpack)","B. Matras","C. Sleeping Bag (Kantong Tidur)","D. Tenda Prisma"]', 'B. Matras'),
(9, 'Tas besar khusus untuk membawa perlengkapan berkemah yang bentuknya dirancang mengikuti anatomi punggung disebut...', '["A. Tenda Prisma","B. Sleeping Bag (Kantong Tidur)","C. Ransel (Carrier / Backpack)","D. Ponco"]', 'C. Ransel (Carrier / Backpack)'),
(9, 'Prinsip dasar saat melakukan "Packing" (mengepak barang ke dalam ransel) agar tidak membuat punggung cepat lelah adalah...', '["A. Ing Madyo Mangun Karso","B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","C. Ikhlas Bakti Bina Bangsa","D. Tut Wuri Handayani"]', 'B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung'),
(9, 'Selain masalah berat, prinsip "Packing" yang baik untuk melindungi barang dari hujan adalah...', '["A. Trisatya dan Dasadarma","B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","C. Ing Ngarso Sung Tulodo","D. Ing Madyo Mangun Karso"]', 'B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang'),
(9, 'Jas hujan berukuran besar berbentuk kelelawar yang dapat dialihfungsikan sebagai atap bivak darurat dinamakan...', '["A. Soenardjo Atmodipuro","B. W.R. Supratman","C. Ponco","D. Rudyard Kipling"]', 'C. Ponco'),
(9, 'Syarat bahan makanan yang ideal untuk dibawa saat perkemahan adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","C. STOP (Stop, Think, Observe, Plan) dan tidak panik","D. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur"]', 'B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak'),
(9, 'Alat masak portabel berbahan aluminium yang sering digunakan oleh militer dan pramuka karena bisa disusun menjadi satu wadah ringkas disebut...', '["A. Racana","B. Barung","C. Nesting","D. Sangga"]', 'C. Nesting'),
(9, 'Lokasi yang TEPAT untuk menyalakan perapian atau kompor saat berkemah adalah...', '["A. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering'),
(9, 'Hal yang mutlak DILARANG dilakukan di dalam tenda karena sangat berbahaya adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Tenda Prisma","C. Matras","D. Groundsheet / Terpal"]', 'A. Menyalakan api, kompor, lentera minyak, atau lilin'),
(9, 'Pembuatan fasilitas MCK (Mandi Cuci Kakus) darurat di area kemah harus berjarak minimal...', '["A. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka"]', 'C. 15-20 meter dari sumber air agar tidak mencemari mata air'),
(9, 'Manajemen sampah di area perkemahan untuk jenis sampah anorganik (plastik, kaleng, kaca) yang paling benar adalah...', '["A. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)'),
(9, 'Sampah organik (sisa makanan) di area perkemahan sebaiknya...', '["A. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain"]', 'B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan'),
(9, 'Saat mengambil air minum dari sungai atau mata air alam, langkah wajib yang harus dilakukan sebelum meminumnya adalah...', '["A. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","D. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak"]', 'B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri'),
(9, 'Api unggun dalam kegiatan perkemahan memiliki fungsi utama sebagai...', '["A. Sleeping Bag (Kantong Tidur)","B. Sarana persaudaraan, kehangatan, dan pertunjukan seni","C. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","D. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda"]', 'B. Sarana persaudaraan, kehangatan, dan pertunjukan seni'),
(9, 'Aturan utama dalam membuat api unggun di alam bebas agar tidak merusak lingkungan adalah...', '["A. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","B. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang"]', 'C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya'),
(9, 'Pakaian lapangan yang ideal untuk berkemah adalah...', '["A. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","C. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","D. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain"]', 'B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)'),
(9, 'Mengapa celana berbahan Jeans/Denim SANGAT TIDAK disarankan dipakai untuk kegiatan kemah di alam bebas?', '["A. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","D. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain"]', 'B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)'),
(9, 'Jenis alas kaki yang paling aman untuk kegiatan perkemahan dan penjelajahan adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)","D. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka"]', 'C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)'),
(9, 'Lembaran kain sintetis kedap air yang sering dipasang di atas tenda untuk menahan air hujan atau dibuat sebagai atap teras dinamakan...', '["A. Flysheet","B. Ki Hajar Dewantara","C. Samuel F.B. Morse","D. Olave St. Clair Soames"]', 'A. Flysheet'),
(9, 'Alat kedap air yang diletakkan di bawah (lantai dasar) tenda agar uap air dari tanah tidak tembus ke dalam dinamakan...', '["A. H. Mutahar","B. Groundsheet / Terpal","C. Andri Bob Sunardi","D. Sri Sultan Hamengkubuwono IX"]', 'B. Groundsheet / Terpal'),
(9, 'Aturan keamanan saat memegang dan berjalan membawa senjata tajam (golok/pisau) di perkemahan adalah...', '["A. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya'),
(9, 'Saat ada anggota yang bertugas piket jaga malam, posisi jaga yang paling benar adalah...', '["A. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","C. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","D. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu"]', 'B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat'),
(9, 'Jika tenda bocor parah di tengah hujan badai malam hari dan seluruh pakaian basah kuyup, ancaman kesehatan paling berbahaya adalah...', '["A. Survival Kit","B. Hipotermia","C. Ransel (Carrier / Backpack)","D. Nesting"]', 'B. Hipotermia'),
(9, 'Etika perkemahan saat malam hari (Quiet Hours) mengharuskan seluruh anggota untuk...', '["A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung"]', 'A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain'),
(9, 'Langkah pertama saat akan membongkar tenda di akhir kegiatan kemah adalah...', '["A. Groundsheet / Terpal","B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","C. Survival Kit","D. Ponco"]', 'B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda'),
(9, 'Syarat utama sebelum melipat kain tenda untuk disimpan ke dalam tas adalah...', '["A. Ransel (Carrier / Backpack)","B. Survival Kit","C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","D. Flysheet"]', 'C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur'),
(9, 'Prinsip pencinta alam "Leave No Trace" (Jangan tinggalkan jejak) mengajarkan kita untuk...', '["A. Ing Ngarso Sung Tulodo","B. Satyaku Kudarmakan, Darmaku Kubaktikan","C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","D. Ikhlas Bakti Bina Bangsa"]', 'C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang'),
(9, 'Kotak atau tas darurat berukuran kecil berisi perlengkapan bertahan hidup esensial (seperti korek anti air, kail pancing, pisau lipat, plester) dinamakan...', '["A. Agnes Baden-Powell","B. Survival Kit","C. Olave St. Clair Soames","D. Andri Bob Sunardi"]', 'B. Survival Kit'),
(9, 'Tindakan yang benar jika tersesat saat melakukan kegiatan penjelajahan di sekitar perkemahan adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. STOP (Stop, Think, Observe, Plan) dan tidak panik","C. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","D. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)"]', 'B. STOP (Stop, Think, Observe, Plan) dan tidak panik'),
(9, 'Fungsi menggunakan pakaian lengan panjang saat menerobos semak/hutan di area kemah adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","C. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","D. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air"]', 'B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga'),
(9, 'Tanda yang dibuat oleh anggota Pramuka menggunakan batu, ranting, atau goresan tanah untuk memberi petunjuk arah di alam bebas disebut...', '["A. Flysheet","B. Tanda Jejak","C. Sleeping Bag (Kantong Tidur)","D. Bivak"]', 'B. Tanda Jejak'),
(9, 'Sikap mental yang paling dituntut dari seorang pemimpin regu saat perkemahan dilanda cuaca buruk adalah...', '["A. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","B. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu","D. 15-20 meter dari sumber air agar tidak mencemari mata air"]', 'C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu'),
(9, 'Obat yang wajib dibawa secara pribadi (tidak boleh mengandalkan regu) saat berkemah adalah...', '["A. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","C. Menyalakan api, kompor, lentera minyak, atau lilin","D. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga"]', 'B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri'),
(9, 'Tujuan akhir setelah kembali dari kegiatan berkemah adalah...', '["A. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya"]', 'B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari'),

-- ==========================================
-- BAB 12: Sandi Morse (Komunikasi)
-- ==========================================
(12, 'Kata "Sandi" berasal dari bahasa Sanskerta, yang memiliki arti...', '["A. Dua garis (--)","B. Rahasia","C. .....","D. --.."]', 'B. Rahasia'),
(12, 'Fungsi utama mempelajari sandi dalam kegiatan kepramukaan adalah untuk...', '["A. Berlawanan / Berkebalikan (Contoh: A >< N)","B. Melatih daya ingat, kecerdasan, dan ketelitian","C. Garis miring ganda (//)","D. Titik"]', 'B. Melatih daya ingat, kecerdasan, dan ketelitian'),
(12, 'Penemu sistem telegraf dan kode Morse adalah seorang seniman dan penemu asal Amerika yang bernama...', '["A. Mayor Kenneth McLaren","B. Samuel F.B. Morse","C. Lord Robert Baden Powell","D. H. Mutahar"]', 'B. Samuel F.B. Morse'),
(12, 'Kode Morse pertama kali ditemukan dan digunakan secara praktis pada tahun...', '["A. 1837","B. 1836","C. 1836","D. 1839"]', 'A. 1837'),
(12, 'Dalam standar internasional, perbandingan durasi waktu antara bunyi/simbol "titik" dan "garis" pada sandi Morse adalah...', '["A. .--","B. 1 : 3","C. .-","D. Titik"]', 'B. 1 : 3'),
(12, 'Huruf yang direpresentasikan dengan satu titik (.) dalam sandi Morse adalah...', '["A. .-.-.","B. E","C. .--.","D. ........"]', 'B. E'),
(12, 'Huruf yang direpresentasikan dengan satu garis (-) dalam sandi Morse adalah...', '["A. -...","B. ........","C. T","D. Dua titik (..)"]', 'C. T'),
(12, 'Kode Morse untuk huruf "A" adalah...', '["A. .-","B. -.","C. --","D. -."]', 'A. .-'),
(12, 'Kode Morse untuk huruf "B" adalah...', '["A. -...","B. ---.","C. ..--","D. .--."]', 'A. -...'),
(12, 'Sinyal marabahaya darurat atau minta tolong standar internasional (SOS) dalam sandi Morse ditulis dengan...', '["A. -.- -.. .-.","B. ... --- ...","C. -.. .-. .--","D. ... .-. ..."]', 'B. ... --- ...'),
(12, 'Kode Morse (...--) melambangkan angka...', '["A. 1","B. 1","C. 3","D. 7"]', 'C. 3'),
(12, 'Kode Morse (---..) melambangkan angka...', '["A. 4","B. 13","C. 8","D. 3"]', 'C. 8'),
(12, 'Kode Morse (----.) melambangkan angka...', '["A. 10","B. 5","C. 9","D. 14"]', 'C. 9'),
(12, 'Tanda pemisah antar kata saat menulis sandi Morse di atas kertas biasanya menggunakan tanda...', '["A. ... --- ...","B. Garis miring ganda (//)","C. Dua garis (--)","D. Darurat / Marabahaya"]', 'B. Garis miring ganda (//)'),
(12, 'Dalam pengiriman pesan Morse, tanda untuk memulai panggilan atau "Attention" biasanya menggunakan kode...', '["A. -.-.-.","B. .-----","C. --.---","D. .--..."]', 'A. -.-.-.'),
(12, 'Isyarat bahwa "Pesan Selesai" (End of Message) dalam pengiriman Morse ditandai dengan kode gabungan huruf AR, yaitu...', '["A. .-.-.","B. ..--.","C. ---..","D. -.-.-"]', 'A. .-.-.'),
(12, 'Jika pengirim melakukan kesalahan saat mengirim sandi Morse, ia memberikan isyarat salah (E 8 kali) yang berbunyi...', '["A. -.----..","B. ........","C. .-..-..-","D. .-..-.--"]', 'B. ........'),
(12, 'Huruf yang secara kode berlawanan dengan A (.-) adalah N, yaitu...', '["A. -.","B. --","C. ..","D. --"]', 'A. -.'),
(12, 'Huruf "O" dalam sandi Morse terdiri dari...', '["A. Tiga garis (---)","B. -----","C. ..-","D. ..-."]', 'A. Tiga garis (---)'),
(12, 'Huruf "S" dalam sandi Morse terdiri dari...', '["A. Tiga titik (...)","B. .--","C. ...-","D. .-.."]', 'A. Tiga titik (...)'),
(12, 'Gabungan huruf S dan O membentuk kata SOS, yang secara universal berarti isyarat...', '["A. .--.","B. Darurat / Marabahaya","C. -.-.-.","D. 1837"]', 'B. Darurat / Marabahaya'),
(12, 'Huruf "I" dalam sandi Morse terdiri dari...', '["A. Rahasia","B. Titik","C. Dua titik (..)","D. .-."]', 'C. Dua titik (..)'),
(12, 'Huruf "M" dalam sandi Morse terdiri dari...', '["A. Titik","B. Dua garis (--)","C. -----","D. 8"]', 'B. Dua garis (--)'),
(12, 'Huruf "C" dalam sandi Morse dituliskan dengan kode...', '["A. -.-.","B. .-..","C. .-..","D. ..--"]', 'A. -.-.'),
(12, 'Huruf "D" dalam sandi Morse dituliskan dengan kode...', '["A. .-.","B. -..","C. ...","D. -.-"]', 'B. -..'),
(12, 'Berlawanan dengan huruf D (-..), huruf "U" dalam sandi morse adalah...', '["A. ..-","B. -..","C. ...","D. ---"]', 'A. ..-'),
(12, 'Huruf "F" dalam sandi Morse adalah...', '["A. ..-.","B. -.-.","C. ....","D. ...-"]', 'A. ..-.'),
(12, 'Huruf "G" dalam sandi Morse adalah...', '["A. ...","B. --.","C. ..-","D. ..-"]', 'B. --.'),
(12, 'Huruf "H" dalam sandi Morse adalah...', '["A. ..-.","B. --..","C. ..-.","D. ...."]', 'D. ....'),
(12, 'Huruf "J" dalam sandi Morse adalah...', '["A. ....","B. -..-","C. .---","D. -..."]', 'C. .---'),
(12, 'Huruf "K" dalam sandi Morse adalah...', '["A. -.-","B. ...","C. .--","D. ---"]', 'A. -.-'),
(12, 'Huruf "L" dalam sandi Morse adalah...', '["A. .---","B. .-..","C. .--.","D. --.-"]', 'B. .-..'),
(12, 'Huruf "P" dalam sandi Morse adalah...', '["A. --.-","B. ...-","C. .--.","D. ----"]', 'C. .--.'),
(12, 'Huruf "Q" dalam sandi Morse adalah...', '["A. --.-","B. .-..","C. --..","D. --.."]', 'A. --.-'),
(12, 'Huruf "R" dalam sandi Morse adalah...', '["A. ---","B. .-.","C. ...","D. ---"]', 'B. .-.'),
(12, 'Huruf "V" dalam sandi Morse adalah...', '["A. --..","B. -.--","C. ...-","D. ----"]', 'C. ...-'),
(12, 'Huruf "W" dalam sandi Morse adalah...', '["A. .--","B. ..-","C. ..-","D. .-."]', 'A. .--'),
(12, 'Huruf "X" dalam sandi Morse adalah...', '["A. ...-","B. -..-","C. .-..","D. ---."]', 'B. -..-'),
(12, 'Huruf "Y" dalam sandi Morse adalah...', '["A. ---.","B. .-..","C. -.--","D. .--."]', 'C. -.--'),
(12, 'Huruf "Z" dalam sandi Morse adalah...', '["A. --..","B. ----","C. ....","D. ----"]', 'A. --..'),
(12, 'Angka 1 dalam sandi Morse ditulis dengan urutan...', '["A. ---.-","B. .----","C. ..-..","D. ..---"]', 'B. .----'),
(12, 'Angka 5 dalam sandi Morse adalah...', '["A. ..-..","B. ..--.","C. .....","D. ---.-"]', 'C. .....'),
(12, 'Angka 0 dalam sandi Morse adalah...', '["A. -----","B. .--..","C. -.---","D. .-.--"]', 'A. -----'),
(12, 'Tanda koma (,) dalam tulisan Morse diwakili dengan gabungan...', '["A. ...-..","B. --..--","C. .-.---","D. ..----"]', 'B. --..--'),
(12, 'Tanda tanya (?) dalam tulisan Morse diwakili dengan gabungan...', '["A. ..--..","B. -.-.--","C. ..-..-","D. ...-.-"]', 'A. ..--..'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan pendek secara internasional mewakili...', '["A. Titik","B. --..--","C. -...","D. ... --- ..."]', 'A. Titik'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan panjang yang keras mewakili...', '["A. .-..","B. Garis","C. .--.","D. -.--"]', 'B. Garis'),
(12, 'Isyarat komunikasi "Tunggu" (AS) yang dikirimkan kepada lawan saat transmisi Morse adalah...', '["A. ---.-","B. .----","C. .-...","D. ..--."]', 'C. .-...'),
(12, 'Isyarat "Mengerti / Pesan Diterima" (R) yang dikirimkan kembali oleh penerima pesan adalah...', '["A. .-.","B. --.","C. ..-","D. ..."]', 'A. .-.'),
(12, 'Cara paling mudah dan umum yang diajarkan dalam pramuka untuk menghafal sandi Morse adalah metode pengelompokan huruf yang saling...', '["A. Melatih daya ingat, kecerdasan, dan ketelitian","B. Berlawanan / Berkebalikan (Contoh: A >< N)","C. --.-","D. ..-"]', 'B. Berlawanan / Berkebalikan (Contoh: A >< N)'),

-- ==========================================
-- BAB 15: Membaca Peta & Navigasi
-- ==========================================
(15, 'Gambar seluruh atau sebagian permukaan bumi yang diproyeksikan pada bidang datar dengan perbandingan skala tertentu disebut...', '["A. Northing","B. Peta","C. Curam / Terjal","D. Resection"]', 'B. Peta'),
(15, 'Jenis peta yang sangat penting bagi Pramuka karena menggambarkan tinggi rendahnya permukaan bumi (relief) secara detail adalah...', '["A. Greenwich, London, Inggris","B. Peta Topografi","C. UTM (Universal Transverse Mercator)","D. Orientasi Peta"]', 'B. Peta Topografi'),
(15, 'Kumpulan penjelasan tentang arti simbol-simbol dan warna yang terdapat pada peta disebut...', '["A. Perindukan","B. Barung","C. Kwartir","D. Legenda Peta"]', 'D. Legenda Peta'),
(15, 'Angka yang menunjukkan perbandingan antara jarak di atas peta dengan jarak sebenarnya di lapangan disebut...', '["A. Garis Kontur","B. Landai / Datar","C. Skala","D. 0 derajat lintang"]', 'C. Skala'),
(15, 'Peta dengan skala 1 : 25.000 berarti 1 cm pada peta mewakili jarak sebenarnya di lapangan sejauh...', '["A. 254 meter","B. 250 meter","C. 254 meter","D. 248 meter"]', 'B. 250 meter'),
(15, 'Jika jarak antara titik A dan B di peta topografi (skala 1:50.000) adalah 4 cm, maka jarak sebenarnya di lapangan adalah...', '["A. 1 kilometer","B. 2 kilometer","C. 6 kilometer","D. 7 kilometer"]', 'B. 2 kilometer'),
(15, 'Skala peta yang ditunjukkan dalam bentuk garis lurus yang terbagi menjadi beberapa ruas dengan ukuran satuan jarak tertentu disebut...', '["A. Kwartir","B. Pasukan","C. Skala Garis (Grafis)","D. Reka"]', 'C. Skala Garis (Grafis)'),
(15, 'Garis khayal melingkar pada peta topografi yang menghubungkan titik-titik dengan ketinggian yang sama dari permukaan laut disebut...', '["A. LU (N - North)","B. Peta","C. Garis Kontur","D. Legenda Peta"]', 'C. Garis Kontur'),
(15, 'Ciri khas utama dari garis kontur adalah jika jarak antar garisnya tergambar sangat rapat, hal itu menunjukkan bentuk medan yang...', '["A. Utara Peta (Grid North)","B. Curam / Terjal","C. Garis Kontur","D. Punggungan (Sadel) / Punggung Bukit"]', 'B. Curam / Terjal'),
(15, 'Jika jarak antar garis kontur di peta terlihat renggang atau saling berjauhan, itu menandakan bentuk medan yang...', '["A. UTM (Universal Transverse Mercator)","B. Skala Garis (Grafis)","C. Landai / Datar","D. 60 menit"]', 'C. Landai / Datar'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" terbalik yang menjorok ke arah ketinggian (menunjuk ke tempat yang lebih tinggi) menandakan bentang alam berupa...', '["A. Pulau Brownsea","B. Lembah / Aliran Sungai","C. Mafeking","D. Gilwell Park"]', 'B. Lembah / Aliran Sungai'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" yang menjorok ke arah tempat yang lebih rendah menandakan bentang alam berupa...', '["A. London","B. Punggungan (Sadel) / Punggung Bukit","C. Afrika Selatan","D. Pulau Brownsea"]', 'B. Punggungan (Sadel) / Punggung Bukit'),
(15, 'Garis kontur yang tergambar berupa lingkaran-lingkaran kecil konsentris yang semakin mengecil di bagian tengah biasanya menandakan...', '["A. Puncak bukit / Gunung","B. 250 meter","C. Skala Garis (Grafis)","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'A. Puncak bukit / Gunung'),
(15, 'Jika ada garis kontur melingkar namun memiliki garis-garis rambut kecil (tick marks) yang mengarah ke bagian dalam lingkaran, itu menandakan...', '["A. LU (N - North)","B. Titik Triangulasi / Ketinggian mutlak (Spot Height)","C. Depresi / Kawah / Cekungan","D. Protractor (Busur Peta)"]', 'C. Depresi / Kawah / Cekungan'),
(15, 'Selisih ketinggian atau jarak vertikal antara satu garis kontur dengan garis kontur di sebelahnya disebut...', '["A. Utara Sebenarnya (True North)","B. Interval Kontur","C. Intersection","D. Puncak bukit / Gunung"]', 'B. Interval Kontur'),
(15, 'Garis kontur yang biasanya dicetak lebih tebal dan disertai angka penunjuk ketinggian untuk mempermudah pembacaan peta disebut...', '["A. UTM (Universal Transverse Mercator)","B. Greenwich, London, Inggris","C. Indeks Kontur","D. Skala"]', 'C. Indeks Kontur'),
(15, 'Sistem garis kisi-kisi (grid) yang membagi peta menjadi kotak-kotak untuk menentukan posisi secara akurat dinamakan koordinat...', '["A. Lord Edward Cecil","B. W.R. Supratman","C. UTM (Universal Transverse Mercator)","D. Lord Robert Baden Powell"]', 'C. UTM (Universal Transverse Mercator)'),
(15, 'Garis vertikal (membujur dari bawah ke atas) pada sistem koordinat kotak (grid) peta yang angkanya dibaca pertama kali (dibaca ke arah Timur) disebut...', '["A. Mafeking","B. Easting","C. Olympia Hall","D. Afrika Selatan"]', 'B. Easting'),
(15, 'Garis horizontal (melintang dari kiri ke kanan) pada sistem koordinat grid peta yang angkanya dibaca kedua (dibaca ke arah Utara) disebut...', '["A. 2 kilometer","B. Northing","C. Resection","D. Landai / Datar"]', 'B. Northing'),
(15, 'Aturan emas (golden rule) dalam membaca koordinat grid di atas peta topografi adalah...', '["A. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","B. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","D. Greenwich, London, Inggris"]', 'C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)'),
(15, 'Jika kita diminta menunjuk titik dengan koordinat 6 digit (contoh: 456 789), ini berarti tingkat ketelitian pencarian lokasi tersebut mencapai area seluas...', '["A. Easting","B. 100 meter persegi","C. Utara Peta (Grid North)","D. Interval Kontur"]', 'B. 100 meter persegi'),
(15, 'Arah Utara yang ditunjukkan oleh garis-garis grid vertikal lurus ke atas pada peta disebut...', '["A. Orientasi Peta","B. Peta Topografi","C. Utara Peta (Grid North)","D. UTM (Universal Transverse Mercator)"]', 'C. Utara Peta (Grid North)'),
(15, 'Arah Utara yang mengarah tepat ke Kutub Utara bumi (poros rotasi) disebut...', '["A. 100 meter persegi","B. Depresi / Kawah / Cekungan","C. Utara Sebenarnya (True North)","D. Orientasi Peta"]', 'C. Utara Sebenarnya (True North)'),
(15, 'Dalam legenda peta topografi standar, warna COKLAT umumnya digunakan untuk menggambarkan...', '["A. Menghitung jumlah langkah kaki ganda (Pacing)","B. Titik Triangulasi / Ketinggian mutlak (Spot Height)","C. Garis ketinggian (Kontur) dan bentang alam darat","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'C. Garis ketinggian (Kontur) dan bentang alam darat'),
(15, 'Warna HIJAU pada peta topografi selalu mengindikasikan adanya...', '["A. Punggungan (Sadel) / Punggung Bukit","B. Kawasan vegetasi / Hutan / Perkebunan","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Jalan raya utama / aspal"]', 'B. Kawasan vegetasi / Hutan / Perkebunan'),
(15, 'Warna BIRU pada peta digunakan secara universal untuk menyimbolkan unsur...', '["A. Menghitung jumlah langkah kaki ganda (Pacing)","B. U atau V terbalik (menjorok ke bawah)","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. Garis ketinggian (Kontur) dan bentang alam darat"]', 'C. Hidrografi / Perairan (Sungai, danau, rawa, laut)'),
(15, 'Warna MERAH pada peta topografi sering kali dikhususkan untuk menandakan unsur penting buatan manusia, yaitu...', '["A. 21 - 25 tahun","B. Jalan raya utama / aspal","C. 16 - 20 tahun","D. 17 - 25 tahun"]', 'B. Jalan raya utama / aspal'),
(15, 'Warna HITAM dalam peta biasanya digunakan untuk mencetak...', '["A. Depresi / Kawah / Cekungan","B. Bagian tepi bawah luar / Margin bawah peta","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Hidrografi / Perairan (Sungai, danau, rawa, laut)"]', 'C. Simbol pemukiman, gedung, jalan setapak, dan tulisan'),
(15, 'Simbol berupa titik hitam dengan bentuk segitiga atau lingkaran disertai angka (misal: ▲ 2100) di peta menunjukkan...', '["A. Sundial / Metode Bayangan Matahari","B. Titik Triangulasi / Ketinggian mutlak (Spot Height)","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. U atau V terbalik (menjorok ke bawah)"]', 'B. Titik Triangulasi / Ketinggian mutlak (Spot Height)'),
(15, 'Tindakan menyamakan posisi arah Utara pada peta agar sejajar dengan arah Utara sebenarnya di lapangan (menggunakan kompas) disebut...', '["A. Orientasi Peta","B. 60 menit","C. LU (N - North)","D. Garis Kontur"]', 'A. Orientasi Peta'),
(15, 'Syarat pertama yang harus dilakukan sebelum melakukan teknik navigasi Resection atau Intersection di lapangan adalah...', '["A. U atau V terbalik (menjorok ke bawah)","B. Melakukan Orientasi Peta terlebih dahulu","C. Garis ketinggian (Kontur) dan bentang alam darat","D. GPS (Global Positioning System)"]', 'B. Melakukan Orientasi Peta terlebih dahulu'),
(15, 'Teknik navigasi untuk menentukan titik koordinat posisi kita sendiri di atas peta, dengan cara membidik dua objek alam yang sudah diketahui di peta, disebut...', '["A. Skala Garis (Grafis)","B. Interval Kontur","C. Resection","D. Garis Kontur"]', 'C. Resection'),
(15, 'Teknik navigasi untuk mencari koordinat posisi objek lain (sasaran) yang belum diketahui di peta, dengan membidiknya dari dua titik stasiun yang berbeda, disebut...', '["A. Atlas","B. Intersection","C. 100 meter persegi","D. Protractor (Busur Peta)"]', 'B. Intersection'),
(15, 'Alat ukur sederhana berbentuk busur derajat berbentuk kotak persegi transparan yang digunakan untuk menghitung sudut dan koordinat langsung di atas peta disebut...', '["A. Afrika Selatan","B. Pulau Brownsea","C. Olympia Hall","D. Protractor (Busur Peta)"]', 'D. Protractor (Busur Peta)'),
(15, 'Alat mekanis kecil dengan roda bergerigi yang dijalankan menyusuri rute lengkung di peta (seperti sungai atau jalan berliku) untuk menghitung jarak disebut...', '["A. Curvimeter","B. Survival Kit","C. Sleeping Bag (Kantong Tidur)","D. Groundsheet / Terpal"]', 'A. Curvimeter'),
(15, 'Penyimpangan sudut yang terjadi antara garis Utara Peta (Grid) dengan Utara Magnetis (Kompas) di suatu wilayah disebut...', '["A. Deklinasi Magnetis","B. Curam / Terjal","C. GPS (Global Positioning System)","D. 100 meter persegi"]', 'A. Deklinasi Magnetis'),
(15, 'Jika kita melipat peta topografi untuk dibawa di saku lapangan, cara melipat yang benar agar peta tidak cepat rusak dan mudah dibaca adalah...', '["A. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","D. Garis Kontur"]', 'C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar'),
(15, 'Saat membaca peta, jika kita berjalan mengikuti punggungan bukit (ridge), maka di peta kita sebenarnya sedang melangkah memotong garis-garis kontur yang berbentuk...', '["A. Jalan raya utama / aspal","B. U atau V terbalik (menjorok ke bawah)","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. Melakukan Orientasi Peta terlebih dahulu"]', 'B. U atau V terbalik (menjorok ke bawah)'),
(15, 'Kumpulan peta dalam satu wujud buku besar dinamakan...', '["A. Atlas","B. W.R. Supratman","C. Sri Sultan Hamengkubuwono IX","D. Lord Robert Baden Powell"]', 'A. Atlas'),
(15, 'Jika tidak memiliki meteran, seorang Pramuka dapat memperkirakan jarak di peta dengan di lapangan menggunakan teknik...', '["A. Menghitung jumlah langkah kaki ganda (Pacing)","B. UTM (Universal Transverse Mercator)","C. Sundial / Metode Bayangan Matahari","D. Simbol pemukiman, gedung, jalan setapak, dan tulisan"]', 'A. Menghitung jumlah langkah kaki ganda (Pacing)'),
(15, 'Garis Khatulistiwa (Equator) yang membelah bumi menjadi Utara dan Selatan ditarik pada derajat...', '["A. 0 derajat lintang","B. Deklinasi Magnetis","C. Easting","D. 2 kilometer"]', 'A. 0 derajat lintang'),
(15, 'Garis Bujur Utama (Prime Meridian) yang menjadi titik 0 derajat dan patokan waktu bumi disepakati melintasi kota...', '["A. Gilwell Park","B. Olympia Hall","C. Greenwich, London, Inggris","D. Nyeri"]', 'C. Greenwich, London, Inggris'),
(15, 'Informasi mengenai tahun pembuatan atau pembaruan peta (update) biasanya dapat ditemukan di...', '["A. Hidrografi / Perairan (Sungai, danau, rawa, laut)","B. Garis ketinggian (Kontur) dan bentang alam darat","C. Bagian tepi bawah luar / Margin bawah peta","D. U atau V terbalik (menjorok ke bawah)"]', 'C. Bagian tepi bawah luar / Margin bawah peta'),
(15, 'Navigasi yang dilakukan di malam hari tanpa kompas dapat mengandalkan Rasi Bintang Pari (Crux) untuk menentukan arah...', '["A. Greenwich, London, Inggris","B. Selatan","C. Deklinasi Magnetis","D. Northing"]', 'B. Selatan'),
(15, 'Navigasi malam hari di belahan bumi utara/tengah dapat menentukan arah Utara dengan mencari konstelasi bintang...', '["A. Ursa Major (Bintang Biduk) / Polaris","B. Depresi / Kawah / Cekungan","C. Garis ketinggian (Kontur) dan bentang alam darat","D. LU (N - North)"]', 'A. Ursa Major (Bintang Biduk) / Polaris'),
(15, 'Alasan mengapa lumut pada pohon lebih sering tumbuh tebal di sisi tertentu (sebagai navigasi darurat penunjuk Timur/Barat) adalah...', '["A. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","D. Punggungan (Sadel) / Punggung Bukit"]', 'B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)'),
(15, 'Metode navigasi alam menggunakan bayangan tongkat kayu yang ditancapkan tegak di tanah pada siang hari disebut metode...', '["A. Skala Garis (Grafis)","B. Sundial / Metode Bayangan Matahari","C. Puncak bukit / Gunung","D. Melakukan Orientasi Peta terlebih dahulu"]', 'B. Sundial / Metode Bayangan Matahari'),
(15, 'Pada peta dengan sistem koordinat grid geografis, Lintang Utara disingkat dengan huruf...', '["A. LU (N - North)","B. Skala Garis (Grafis)","C. Utara Peta (Grid North)","D. Menghitung jumlah langkah kaki ganda (Pacing)"]', 'A. LU (N - North)'),
(15, 'Satu derajat (1°) dalam sistem koordinat Geografis (DMS) dibagi lagi menjadi...', '["A. 58 menit","B. 60 menit","C. 65 menit","D. 65 menit"]', 'B. 60 menit'),
(15, 'Sistem Penentuan Posisi Global yang mengandalkan perangkat elektronik untuk menerima sinyal satelit navigasi bumi disebut...', '["A. Skala Garis (Grafis)","B. Garis Kontur","C. GPS (Global Positioning System)","D. Indeks Kontur"]', 'C. GPS (Global Positioning System)'),

-- ==========================================
-- BAB 20: Macam-Macam Sandi
-- ==========================================
(20, 'Sandi yang menggunakan bentuk garis vertikal, horizontal, dan titik sebagai pengganti huruf disebut...', '["A. Huruf Konsonan, contohnya K","B. Sandi Kotak 1","C. Tanda Titik (.) pada Morse","D. Sandi AND"]', 'B. Sandi Kotak 1'),
(20, 'Sandi Kotak 1 terdiri dari dua macam bentuk pola kerangka dasar, yaitu...', '["A. London","B. Palang tegak lurus dan silang (X)","C. Olympia Hall","D. Pulau Brownsea"]', 'B. Palang tegak lurus dan silang (X)'),
(20, 'Dalam Sandi Kotak 1, masing-masing ruangan kotak pada kerangka palang maksimal diisi oleh...', '["A. 5 huruf","B. 2 huruf","C. 3 huruf","D. 5 huruf"]', 'B. 2 huruf'),
(20, 'Dalam Sandi Kotak 1, huruf "B" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. 4 titik","B. 1 titik","C. 5 titik","D. 3 titik"]', 'B. 1 titik'),
(20, 'Dalam Sandi Kotak 1, huruf "A" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. Tanpa titik","B. Olympia Hall","C. Mafeking","D. London"]', 'A. Tanpa titik'),
(20, 'Dalam Sandi Kotak 1, huruf "N" yang berada di kerangka silang (X) digambarkan dengan bentuk huruf V yang terbuka ke bawah, ditambah dengan...', '["A. Tanpa titik","B. Nyeri","C. London","D. Olympia Hall"]', 'A. Tanpa titik'),
(20, 'Perbedaan utama antara Sandi Kotak 1 dan Sandi Kotak 2 (versi Boyman) terletak pada penempatan huruf, yaitu...', '["A. Afrika Selatan","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. London","D. Nyeri"]', 'B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik'),
(20, 'Dalam Sandi Kotak 2, huruf "C" ditandai dengan kotak yang sama dengan huruf A dan B, namun dibedakan menggunakan...', '["A. London","B. Pulau Brownsea","C. Menggunakan 2 titik","D. Olympia Hall"]', 'C. Menggunakan 2 titik'),
(20, 'Sandi Kotak 3 memiliki bentuk dasar kerangka yang unik dan sedikit rumit, yaitu berbentuk susunan...', '["A. Olympia Hall","B. Belah ketupat (segi empat silang)","C. Afrika Selatan","D. Kenya"]', 'B. Belah ketupat (segi empat silang)'),
(20, 'Sandi Rumput pada dasarnya merupakan bentuk kamuflase atau aplikasi visual murni dari...', '["A. CENZHXN","B. MERAH PUTIH","C. Sandi Morse","D. Sandi Jam"]', 'C. Sandi Morse'),
(20, 'Pada Sandi Rumput, lambang titik (.) pada kode morse digambarkan dengan wujud...', '["A. 6","B. Rumput pendek","C. Semaphore","D. Rahasia"]', 'B. Rumput pendek'),
(20, 'Pada Sandi Rumput, lambang garis (-) pada kode morse digambarkan dengan wujud...', '["A. Rumput tinggi","B. Morse dan Semaphore","C. 1 titik","D. 6"]', 'A. Rumput tinggi'),
(20, 'Sandi yang mengubah urutan abjad sedemikian rupa sehingga abjad dibagi dua, huruf "A" dibaca "N", "B" dibaca "O", dan seterusnya, disebut...', '["A. C","B. Sandi AN","C. Morse dan Semaphore","D. OH"]', 'B. Sandi AN'),
(20, 'Kata "PRAMUKA" jika dipecahkan menggunakan rumus abjad Sandi AN akan berbunyi...', '["A. CENZHXN","B. Rumput pendek","C. A-N-I-B-M-E-P","D. Morse dan Semaphore"]', 'A. CENZHXN'),
(20, 'Sandi yang menukar huruf awal alfabet dengan huruf akhir (A menjadi Z, B menjadi Y, C menjadi X) disebut...', '["A. Sandi AZ / Sandi Balik Abjad","B. 10 huruf tanpa ada huruf ganda yang sama","C. Huruf Konsonan, contohnya K","D. Tanda Garis (-) pada Morse"]', 'A. Sandi AZ / Sandi Balik Abjad'),
(20, 'Kata "PRAMUKA" jika dibaca ke dalam rumus Sandi AZ maka akan menjadi susunan huruf...', '["A. Sandi Jam","B. KIZNFPZ","C. Louis Braille","D. 2"]', 'B. KIZNFPZ'),
(20, 'Dalam Sandi Angka dasar, di mana A=1, B=2, dst., maka susunan kode 16-18-1-13-21-11-1 dibaca...', '["A. Sandi AND","B. Tanpa titik","C. PRAMUKA","D. 1 titik"]', 'C. PRAMUKA'),
(20, 'Sandi Angka juga bisa divariasikan patokannya (misal awalan A=0). Jika A=0, maka huruf C adalah angka...', '["A. 5","B. 7","C. 2","D. 5"]', 'C. 2'),
(20, 'Sandi yang pengerjaannya menggunakan dua kata kunci yang digabungkan membentuk tabel baris dan kolom persilangan, disebut...', '["A. Merah dan Kuning","B. Sandi Koordinat","C. KIZNFPZ","D. Menggunakan 2 titik"]', 'B. Sandi Koordinat'),
(20, 'Dua buah kata yang paling sering dan umum dijadikan kata kunci dalam Sandi Koordinat Pramuka adalah...', '["A. MERAH PUTIH","B. A-N-I-B-M-E-P","C. KIZNFPZ","D. Sandi AND"]', 'A. MERAH PUTIH'),
(20, 'Dalam Sandi Koordinat "MERAH PUTIH", huruf "M" mewakili posisi...', '["A. Rumput tinggi","B. Baris pertama","C. Rumput pendek","D. C"]', 'B. Baris pertama'),
(20, 'Sandi yang memanfaatkan patokan interval selisih waktu secara berurutan sebagai pengganti abjad alfabet disebut...', '["A. Sandi AND","B. Semaphore","C. Sandi Jam","D. Merah dan Kuning"]', 'C. Sandi Jam'),
(20, 'Pada Sandi Jam, jika disepakati pukul 08.00 adalah huruf A, dan interval beda waktu adalah 5 menit, maka huruf B ditulis pada...', '["A. Rumput pendek","B. 08.05","C. Morse dan Semaphore","D. Sandi Koordinat"]', 'B. 08.05'),
(20, 'Jika pukul 07.00 = A dengan interval waktu yang sama yaitu 5 menit, jam berapakah yang akan menunjukkan huruf C?', '["A. Sandi Jam","B. 07.10","C. Rahasia","D. PRAMUKA"]', 'B. 07.10'),
(20, 'Sandi yang mengadopsi cara penulisan unsur rumus kimia, dan sebenarnya merupakan kamuflase lain dari sandi Morse, disebut...', '["A. 1 titik","B. CENZHXN","C. Sandi Kimia","D. Sandi AN"]', 'C. Sandi Kimia'),
(20, 'Dalam ketentuan Sandi Kimia Pramuka, kelompok huruf Vokal (A, I, U, E, O) berfungsi menggantikan posisi...', '["A. Tanda Titik (.) pada Morse","B. Sandi AZ / Sandi Balik Abjad","C. Morse dan Semaphore","D. Sandi Pecahan / Sandi Matematika"]', 'A. Tanda Titik (.) pada Morse'),
(20, 'Dalam Sandi Kimia, kelompok huruf Konsonan (B, C, D, F, dst) berfungsi menggantikan posisi...', '["A. Tanda Titik (.) pada Morse","B. Tanda Garis (-) pada Morse","C. Sandi Pecahan / Sandi Matematika","D. Morse dan Semaphore"]', 'B. Tanda Garis (-) pada Morse'),
(20, 'Kode Morse ".-" (Huruf A) jika diubah ke dalam Sandi Kimia bisa ditulis menjadi wujud kombinasi Vokal-Konsonan bebas, misalnya...', '["A. OH","B. Sandi Kotak 1","C. MERAH PUTIH","D. C"]', 'A. OH'),
(20, 'Sandi kata yang cara menyembunyikannya adalah dengan menyisipkan huruf/kata "AND" di antara abjad aslinya disebut...', '["A. Sandi Koordinat","B. Sandi Morse","C. Sandi AND","D. 45 x 45 cm"]', 'C. Sandi AND'),
(20, 'Sandi yang bentuk aslinya menyerupai lekukan garis-garis bergelombang tak terputus, di mana lekukan kecil adalah titik dan lekukan besar/runcing adalah garis, dinamakan...', '["A. Rudyard Kipling","B. Lord Robert Baden Powell","C. Sri Sultan Hamengkubuwono IX","D. Sandi Ular / Sandi Gergaji"]', 'D. Sandi Ular / Sandi Gergaji'),
(20, 'Sandi yang cara membacanya sama dengan metode membaca aksara Arab, yaitu dibaca terbalik dari kanan ke kiri, disebut...', '["A. Sandi Kimia","B. KIZNFPZ","C. Sandi Arab","D. Menggunakan 2 titik"]', 'C. Sandi Arab'),
(20, 'Sebuah pesan tertulis "AKUMARP", jika dipecahkan menggunakan kaidah Sandi Arab akan dapat dibaca menjadi kata...', '["A. PRAMUKA","B. Morse dan Semaphore","C. 1 titik","D. Rumput tinggi"]', 'A. PRAMUKA'),
(20, 'Sandi yang cara membacanya memutar seperti cangkang kerang dari tengah ke luar atau luar ke dalam berlawanan jarum jam disebut...', '["A. 08.05","B. Sandi Kimia","C. Sandi Siput","D. Sandi Kotak 1"]', 'C. Sandi Siput'),
(20, 'Sandi yang menggunakan titik-titik timbul untuk membantu penyandang tunanetra membaca, yang diciptakan di Prancis adalah...', '["A. Louis Braille","B. 2 huruf","C. PRAMUKA","D. Morse dan Semaphore"]', 'A. Louis Braille'),
(20, 'Susunan titik pada Sandi Braille dibentuk berdasarkan pola sebuah kotak imajiner yang berukuran...', '["A. Mafeking","B. 2 kolom dan 3 baris (total 6 titik posisi)","C. Afrika Selatan","D. Olympia Hall"]', 'B. 2 kolom dan 3 baris (total 6 titik posisi)'),
(20, 'Isyarat komunikasi jarak jauh yang menggunakan peraga sepasang bendera tangan dan sering masuk dalam materi wawasan komunikasi Pramuka disebut...', '["A. Sandi AN","B. 2 huruf","C. A-N-I-B-M-E-P","D. Semaphore"]', 'D. Semaphore'),
(20, 'Ukuran standar bendera Semaphore yang biasa digunakan oleh Pramuka Penggalang adalah persegi dengan ukuran...', '["A. 45 x 45 cm","B. Baris pertama","C. Sandi Ular / Sandi Gergaji","D. Sandi AN"]', 'A. 45 x 45 cm'),
(20, 'Warna standar untuk bendera Semaphore agar mudah terlihat dari jarak jauh adalah perpaduan menyilang dari warna...', '["A. Tanda Garis (-) pada Morse","B. Merah dan Kuning","C. OH","D. C"]', 'B. Merah dan Kuning'),
(20, 'Dalam Sandi Kotak 1, huruf "Z" digambarkan menempati kerangka silang (X) pada sudut bawah dengan ditambahkan...', '["A. 5 titik","B. 2 titik","C. 1 titik","D. 2 titik"]', 'C. 1 titik'),
(20, 'Sandi yang memanipulasi abjad Morse ke dalam bentuk angka pembilang dan penyebut pecahan matematika disebut...', '["A. Sandi Pecahan / Sandi Matematika","B. Tanda Garis (-) pada Morse","C. Morse dan Semaphore","D. Palang tegak lurus dan silang (X)"]', 'A. Sandi Pecahan / Sandi Matematika'),
(20, 'Pada variasi Sandi Angka, jika disepakati A=3, B=4, maka huruf D akan ditulis menggunakan angka...', '["A. 2","B. 6","C. 3","D. 10"]', 'B. 6'),
(20, 'Huruf "E" dalam kode morse hanya terdiri dari satu titik. Dalam Sandi Kimia, huruf E dapat diwakilkan cukup dengan satu huruf saja, misalnya...', '["A. Huruf Vokal, contohnya O","B. Sir Arthur Conan Doyle (Sherlock Holmes)","C. Louis Braille","D. Rumput pendek"]', 'A. Huruf Vokal, contohnya O'),
(20, 'Huruf "T" dalam kode morse hanya terdiri dari satu garis. Dalam Sandi Kimia, huruf T dapat diwakilkan cukup dengan satu huruf, misalnya...', '["A. Sandi Pecahan / Sandi Matematika","B. Huruf Konsonan, contohnya K","C. Sandi Kimia","D. Merah dan Kuning"]', 'B. Huruf Konsonan, contohnya K'),
(20, 'Syarat utama dua buah kata yang akan dijadikan kunci dalam tabel baris/kolom Sandi Koordinat adalah gabungan katanya harus terdiri dari...', '["A. Palang tegak lurus dan silang (X)","B. Sir Arthur Conan Doyle (Sherlock Holmes)","C. 10 huruf tanpa ada huruf ganda yang sama","D. 2 kolom dan 3 baris (total 6 titik posisi)"]', 'C. 10 huruf tanpa ada huruf ganda yang sama'),
(20, 'Kata "Sandi" itu sendiri berarti...', '["A. Rumput tinggi","B. Rahasia","C. KIZNFPZ","D. Louis Braille"]', 'B. Rahasia'),
(20, 'Tujuan asli dibentuknya sandi atau kriptografi pada zaman dahulu yang menginspirasi kepramukaan adalah...', '["A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. Baris pertama","D. 2 huruf"]', 'A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh'),
(20, 'Jika Sandi Jam dimulai pukul 10.00 = A, dan beda waktu intervalnya dinaikkan menjadi 10 menit, maka pukul 10.20 menunjukkan huruf...', '["A. 2","B. Merah dan Kuning","C. C","D. KIZNFPZ"]', 'C. C'),
(20, 'Sandi rahasia unik yang menggunakan bentuk gambar tongkat orang menari dengan posisi lengan berbeda-beda (Dancing Men) terinspirasi dari novel karya...', '["A. Sir Arthur Conan Doyle (Sherlock Holmes)","B. 45 x 45 cm","C. Sandi AZ / Sandi Balik Abjad","D. 10 huruf tanpa ada huruf ganda yang sama"]', 'A. Sir Arthur Conan Doyle (Sherlock Holmes)'),
(20, '"P-E-M-B-I-N-A" jika ditulis menggunakan rumus Sandi Arab akan menjadi susunan...', '["A. Merah dan Kuning","B. A-N-I-B-M-E-P","C. 1 titik","D. C"]', 'B. A-N-I-B-M-E-P'),
(20, 'Salah satu Syarat Kecakapan Umum (SKU) Pramuka Penggalang mewajibkan anggotanya untuk dapat memahami, membaca, dan mengirimkan pesan isyarat dasar yaitu...', '["A. 45 x 45 cm","B. Tanpa titik","C. Morse dan Semaphore","D. Rumput tinggi"]', 'C. Morse dan Semaphore'),

-- ==========================================
-- BAB 24: P3K & Kesehatan
-- ==========================================
(24, 'Singkatan dari P3K adalah...', '["A. 36-37 derajat","B. Pertolongan Pertama Pada Kecelakaan","C. Manuver Heimlich (hentakan pada perut)","D. Lebih tinggi dari kepala (Elevasi)"]', 'B. Pertolongan Pertama Pada Kecelakaan'),
(24, 'Tujuan utama dari pemberian P3K adalah...', '["A. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","C. Menundukkan kepala ke depan dan menjepit cuping hidung","D. Henti napas dan henti jantung"]', 'B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk'),
(24, 'Langkah pertama yang harus dilakukan saat menemukan korban kecelakaan adalah...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","C. Balut tekan (tekan langsung di atas luka)","D. Tenang, Cepat, Tepat, dan Tidak Panik"]', 'B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)'),
(24, 'Pembalut segitiga yang sangat sering digunakan dalam P3K Pramuka disebut...', '["A. Oralit","B. Tandu Darurat (Dragbar)","C. Mitela","D. Balutan angka delapan"]', 'C. Mitela'),
(24, 'Alat keras/kaku yang digunakan untuk menahan tulang yang patah agar tidak bergerak disebut...', '["A. Nesting","B. Bidai / Spalk","C. Tenda Prisma","D. Sleeping Bag (Kantong Tidur)"]', 'B. Bidai / Spalk'),
(24, 'Pertolongan pertama pada korban mimisan yang benar adalah...', '["A. Gigitan hewan (anjing/kucing) untuk cegah rabies","B. Menundukkan kepala ke depan dan menjepit cuping hidung","C. Dialiri air bersih mengalir selama 10-15 menit","D. Menutup luka agar tidak infeksi dan menyerap darah"]', 'B. Menundukkan kepala ke depan dan menjepit cuping hidung'),
(24, 'Pendarahan arteri ditandai dengan ciri-ciri...', '["A. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","B. Darah memancar seirama denyut jantung dan berwarna merah terang","C. Nadi cepat dan lemah, kulit pucat, keringat dingin","D. Mencegah kulit korban terluka saat menggunting perban"]', 'B. Darah memancar seirama denyut jantung dan berwarna merah terang'),
(24, 'Cara menghentikan pendarahan luar yang paling efektif adalah dengan teknik...', '["A. Balut tekan (tekan langsung di atas luka)","B. Minyak Kayu Putih / Kaladin","C. Dialiri air bersih mengalir selama 10-15 menit","D. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)"]', 'A. Balut tekan (tekan langsung di atas luka)'),
(24, 'Simpul yang digunakan untuk mengakhiri balutan mitela agar mudah dilepas adalah...', '["A. Simpul Mati (Reef Knot)","B. Simpul Mati","C. Simpul Anyam (Sheet Bend)","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'B. Simpul Mati'),
(24, 'Kondisi penurunan suhu tubuh secara drastis akibat cuaca dingin di gunung disebut...', '["A. Antiseptik (Betadine/Rivanol)","B. Hipotermia","C. Demam Berdarah (Dengue)","D. Balutan angka delapan"]', 'B. Hipotermia'),
(24, 'Pertolongan pertama pada luka bakar ringan (derajat 1) adalah...', '["A. Mencegah kulit korban terluka saat menggunting perban","B. Dialiri air bersih mengalir selama 10-15 menit","C. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","D. Lebih tinggi dari kepala (Elevasi)"]', 'B. Dialiri air bersih mengalir selama 10-15 menit'),
(24, 'Alat untuk mengangkut korban kecelakaan secara darurat yang dibuat dari dua tongkat dan tali disebut...', '["A. Nesting","B. Tandu Darurat (Dragbar)","C. Flysheet","D. Sleeping Bag (Kantong Tidur)"]', 'B. Tandu Darurat (Dragbar)'),
(24, 'Jumlah ikatan minimal pada pemasangan bidai untuk patah tulang tungkai bawah adalah...', '["A. Simpul Pangkal (Clove Hitch)","B. Simpul Tiang (Bowline)","C. Simpul Tali Tenda (Taut-line Hitch)","D. Minimal melewati dua sendi"]', 'D. Minimal melewati dua sendi'),
(24, 'Korban pingsan sebaiknya diposisikan telentang dengan posisi kaki...', '["A. Bidai / Spalk","B. Perilaku Hidup Bersih dan Sehat (PHBS)","C. Lebih tinggi dari kepala (Elevasi)","D. Dialiri air bersih mengalir selama 10-15 menit"]', 'C. Lebih tinggi dari kepala (Elevasi)'),
(24, 'Isi kotak P3K yang berfungsi untuk membersihkan luka dari kuman adalah...', '["A. Mafeking","B. Antiseptik (Betadine/Rivanol)","C. Gilwell Park","D. Olympia Hall"]', 'B. Antiseptik (Betadine/Rivanol)'),
(24, 'Penyakit yang disebabkan oleh gigitan nyamuk Aedes Aegypti adalah...', '["A. Belakang (berlawanan arah jalan)","B. Demam Berdarah (Dengue)","C. Tandu Darurat (Dragbar)","D. 2-4 orang"]', 'B. Demam Berdarah (Dengue)'),
(24, 'Cara menangani kaki yang terkilir (kram/keseleo) dengan metode RICE, singkatan dari...', '["A. Tenang, Cepat, Tepat, dan Tidak Panik","B. Rest, Ice, Compression, Elevation","C. Bidai / Spalk","D. Balutan angka delapan"]', 'B. Rest, Ice, Compression, Elevation'),
(24, 'Pertolongan pertama jika seseorang tersedak makanan dan sulit bernapas adalah dengan...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. Manuver Heimlich (hentakan pada perut)","C. Mencoba meluruskan posisi tulang secara paksa","D. Tenang, Cepat, Tepat, dan Tidak Panik"]', 'B. Manuver Heimlich (hentakan pada perut)'),
(24, 'Obat yang digunakan untuk mengurangi rasa sakit kepala atau demam ringan adalah...', '["A. Gunting","B. Parasetamol","C. Mitela","D. Tandu Darurat (Dragbar)"]', 'B. Parasetamol'),
(24, 'Untuk mengganti cairan tubuh yang hilang akibat diare, sebaiknya diberikan...', '["A. Antiseptik (Betadine/Rivanol)","B. Oralit","C. 2-4 orang","D. Lengan / Bahu"]', 'B. Oralit'),
(24, 'Pembalutan pada luka di kepala biasanya menggunakan mitela yang dilipat menjadi bentuk...', '["A. Bidai / Spalk","B. Segitiga terbuka","C. Oralit","D. 30 : 2"]', 'B. Segitiga terbuka'),
(24, 'Luka yang disebabkan oleh benda tumpul dan menyebabkan memar kebiruan disebut luka...', '["A. Henti napas dan henti jantung","B. Luka Memar (Contusio)","C. Rest, Ice, Compression, Elevation","D. Lebih tinggi dari kepala (Elevasi)"]', 'B. Luka Memar (Contusio)'),
(24, 'Tindakan RJP (Resusitasi Jantung Paru) dilakukan pada korban yang...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. Henti napas dan henti jantung","C. Tenang, Cepat, Tepat, dan Tidak Panik","D. Tandu Darurat (Dragbar)"]', 'B. Henti napas dan henti jantung'),
(24, 'Pada saat memindahkan korban dengan tandu, posisi kepala korban sebaiknya berada di...', '["A. Simpul Mati","B. Belakang (berlawanan arah jalan)","C. Luka Memar (Contusio)","D. Pertolongan Pertama Pada Kecelakaan"]', 'B. Belakang (berlawanan arah jalan)'),
(24, 'Warna kotak P3K standar biasanya adalah...', '["A. Mafeking","B. Putih dengan tanda palang merah/hijau","C. Afrika Selatan","D. Olympia Hall"]', 'B. Putih dengan tanda palang merah/hijau'),
(24, 'Pertolongan pertama pada gigitan ular yang paling tepat adalah...', '["A. Darah memancar seirama denyut jantung dan berwarna merah terang","B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS","D. Menundukkan kepala ke depan dan menjepit cuping hidung"]', 'C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS'),
(24, 'Pembalut elastis (Elastic Bandage) sangat baik digunakan untuk menangani...', '["A. Antiseptik (Betadine/Rivanol)","B. Terkilir / Cedera sendi","C. Gigitan hewan (anjing/kucing) untuk cegah rabies","D. Perilaku Hidup Bersih dan Sehat (PHBS)"]', 'B. Terkilir / Cedera sendi'),
(24, 'Penyakit yang sering muncul di perkemahan akibat sanitasi buruk dan air kotor adalah...', '["A. Antasida","B. Diare","C. Oralit","D. Luka Memar (Contusio)"]', 'B. Diare'),
(24, 'Kasa steril diletakkan langsung di atas luka bertujuan untuk...', '["A. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","B. Menutup luka agar tidak infeksi dan menyerap darah","C. 50-100 cm (agar tidak dibongkar hewan)","D. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS"]', 'B. Menutup luka agar tidak infeksi dan menyerap darah'),
(24, 'Berapa jumlah penolong yang ideal untuk mengangkat tandu darurat?', '["A. Mitela","B. 2-4 orang","C. Simpul Mati","D. Susu / Air kelapa"]', 'B. 2-4 orang'),
(24, 'Alat untuk mengukur suhu tubuh manusia disebut...', '["A. 11 - 15 tahun","B. Termometer","C. 7 - 10 tahun","D. 16 - 20 tahun"]', 'B. Termometer'),
(24, 'Suhu tubuh normal manusia berkisar antara...', '["A. 11 - 15 tahun","B. 36-37 derajat","C. 7 - 10 tahun","D. 14 - 18 tahun"]', 'B. 36-37 derajat'),
(24, 'Tindakan yang harus dihindari saat menolong korban patah tulang adalah...', '["A. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","B. Mencoba meluruskan posisi tulang secara paksa","C. Nadi cepat dan lemah, kulit pucat, keringat dingin","D. Air bersih / Boorwater"]', 'B. Mencoba meluruskan posisi tulang secara paksa'),
(24, 'Mencuci tangan sebelum makan dan setelah beraktivitas merupakan contoh...', '["A. Gigitan hewan (anjing/kucing) untuk cegah rabies","B. Perilaku Hidup Bersih dan Sehat (PHBS)","C. Pinset dan air bersih","D. 50-100 cm (agar tidak dibongkar hewan)"]', 'B. Perilaku Hidup Bersih dan Sehat (PHBS)'),
(24, 'Cairan yang digunakan untuk mencuci mata jika kemasukan debu adalah...', '["A. Mencoba meluruskan posisi tulang secara paksa","B. Air bersih / Boorwater","C. 50-100 cm (agar tidak dibongkar hewan)","D. Balutan angka delapan"]', 'B. Air bersih / Boorwater'),
(24, 'Pembalut Mitela dilipat menjadi "Gendongan" berfungsi untuk menyangga cedera pada...', '["A. Minimal melewati dua sendi","B. Lengan / Bahu","C. Simpul Mati","D. Mitela"]', 'B. Lengan / Bahu'),
(24, 'Tanda-tanda seseorang mengalami syok (shock) adalah...', '["A. Menundukkan kepala ke depan dan menjepit cuping hidung","B. Nadi cepat dan lemah, kulit pucat, keringat dingin","C. Tenang, Cepat, Tepat, dan Tidak Panik","D. Menyelamatkan nyawa dan mencegah kondisi korban memburuk"]', 'B. Nadi cepat dan lemah, kulit pucat, keringat dingin'),
(24, 'Zat racun dalam makanan dapat dinetralkan sementara (sebelum ke dokter) dengan meminum...', '["A. Susu / Air kelapa","B. Antiseptik (Betadine/Rivanol)","C. 30 : 2","D. Belakang (berlawanan arah jalan)"]', 'A. Susu / Air kelapa'),
(24, 'Obat luar yang digunakan untuk meredakan gatal akibat gigitan serangga adalah...', '["A. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","B. Minyak Kayu Putih / Kaladin","C. Belakang (berlawanan arah jalan)","D. Luka Memar (Contusio)"]', 'B. Minyak Kayu Putih / Kaladin'),
(24, 'Luka tusuk akibat paku berkarat sangat berisiko menyebabkan penyakit...', '["A. Bidai / Spalk","B. Tetanus","C. Lengan / Bahu","D. Demam Berdarah (Dengue)"]', 'B. Tetanus'),
(24, 'Pada RJP (CPR), rasio kompresi dada dan napas buatan untuk satu penolong adalah...', '["A. Minyak Kayu Putih / Kaladin","B. 30 : 2","C. Simpul Mati","D. Lebih tinggi dari kepala (Elevasi)"]', 'B. 30 : 2'),
(24, 'Pembalutan luka di lutut yang sedang ditekuk paling baik menggunakan teknik...', '["A. Balutan angka delapan","B. Susu / Air kelapa","C. Demam Berdarah (Dengue)","D. Oralit"]', 'A. Balutan angka delapan'),
(24, 'Bagian dari tas P3K yang digunakan untuk memotong perban atau pakaian korban adalah...', '["A. Luka Memar (Contusio)","B. Gunting","C. Simpul Mati","D. Mitela"]', 'B. Gunting'),
(24, 'Untuk membersihkan luka yang kotor dari kerikil atau pasir digunakan...', '["A. Putih dengan tanda palang merah/hijau","B. Pinset dan air bersih","C. Henti napas dan henti jantung","D. Terkilir / Cedera sendi"]', 'B. Pinset dan air bersih'),
(24, 'Apa yang harus dilakukan jika korban tersambar petir?', '["A. Henti napas dan henti jantung","B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS","C. Pertolongan Pertama Pada Kecelakaan","D. Air bersih / Boorwater"]', 'B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS'),
(24, 'Gunting yang bagian ujungnya tumpul (Gunting Verban) bertujuan untuk...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. Mencegah kulit korban terluka saat menggunting perban","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Balut tekan (tekan langsung di atas luka)"]', 'B. Mencegah kulit korban terluka saat menggunting perban'),
(24, 'Kesehatan lingkungan perkemahan dijaga dengan cara membuat lubang sampah sedalam...', '["A. Air bersih / Boorwater","B. 50-100 cm (agar tidak dibongkar hewan)","C. Mencoba meluruskan posisi tulang secara paksa","D. Gigitan hewan (anjing/kucing) untuk cegah rabies"]', 'B. 50-100 cm (agar tidak dibongkar hewan)'),
(24, 'Obat yang digunakan untuk menolong sakit perut akibat maag adalah...', '["A. Segitiga terbuka","B. Antasida","C. 30 : 2","D. Hipotermia"]', 'B. Antasida'),
(24, 'Mencuci luka dengan air sabun sangat disarankan khusus untuk luka akibat...', '["A. Balut tekan (tekan langsung di atas luka)","B. Gigitan hewan (anjing/kucing) untuk cegah rabies","C. Henti napas dan henti jantung","D. Rest, Ice, Compression, Elevation"]', 'B. Gigitan hewan (anjing/kucing) untuk cegah rabies'),
(24, 'Prinsip utama penolong P3K adalah...', '["A. Tut Wuri Handayani","B. Tenang, Cepat, Tepat, dan Tidak Panik","C. Good Turn (Berbuat Kebaikan)","D. Trisatya dan Dasadarma"]', 'B. Tenang, Cepat, Tepat, dan Tidak Panik'),

-- ==========================================
-- BAB 99: Tambahan / Campuran
-- ==========================================
(99, 'Gerakan kepanduan di Indonesia resmi diakui dan menjadi anggota WOSM (World Organization of the Scout Movement) pada tahun...', '["A. 1952","B. 1953","C. 1955","D. 1957"]', 'B. 1953'),
(99, 'Sifat kepramukaan yang berarti penyelenggaraannya disesuaikan dengan keadaan, kebutuhan, dan kepentingan masyarakat di negaranya adalah sifat...', '["A. Olympia Hall","B. Nasional","C. Kenya","D. Pulau Brownsea"]', 'B. Nasional'),
(99, 'Semboyan Sistem Among "Ing Madyo Mangun Karso" memiliki arti seorang Pembina harus mampu...', '["A. Dwisatya dan Dwidarma","B. Di tengah membangun kemauan/semangat","C. Trisatya dan Dasadarma","D. Tut Wuri Handayani"]', 'B. Di tengah membangun kemauan/semangat'),
(99, 'Tanda Kecakapan Khusus (TKK) tingkat tertinggi yang bentuknya segilima beraturan adalah tingkat...', '["A. Bantara, Laksana","B. Mula, Bantu, Tata","C. Utama","D. Pramuka Garuda"]', 'C. Utama'),
(99, 'Undang-Undang Republik Indonesia yang secara khusus mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. Di tengah membangun kemauan/semangat","B. UU No. 12 Tahun 2010","C. Rest, Ice, Compression, Elevation","D. 1 : 3"]', 'B. UU No. 12 Tahun 2010'),
(99, 'Bapak Pandu Dunia (Chief Scout of the World) dan Bapak Pramuka Indonesia secara berurutan adalah...', '["A. Samuel F.B. Morse","B. Lord Robert Baden Powell","C. Baden Powell dan Sri Sultan Hamengkubuwono IX","D. Agnes Baden-Powell"]', 'C. Baden Powell dan Sri Sultan Hamengkubuwono IX'),
(99, 'Penggolongan usia Pramuka Penegak yang tepat adalah...', '["A. 7 - 10 tahun","B. 17 - 25 tahun","C. 16 - 20 tahun","D. 11 - 15 tahun"]', 'C. 16 - 20 tahun'),
(99, 'Meskipun lekat dengan dunia militer, ayah dari Baden-Powell sejatinya adalah seorang...', '["A. 45-60 derajat berlawanan dengan arah tarikan tali tenda","B. Guru Besar Geometri di Universitas Oxford","C. Baden Powell dan Sri Sultan Hamengkubuwono IX","D. Serigala yang tidak pernah tidur"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(99, 'Suku-suku di Afrika memberikan julukan "Impeesa" kepada Baden-Powell, yang memiliki makna filosofis...', '["A. Sandi Ular / Sandi Gergaji","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. Serigala yang tidak pernah tidur","D. Saya telah pulang"]', 'C. Serigala yang tidak pernah tidur'),
(99, 'Buku mahakarya Baden-Powell yang ditujukan khusus untuk golongan pemuda (Rover Scout) pada tahun 1922 berjudul...', '["A. Boyman","B. The Jungle Book","C. Scouting for Boys","D. Rovering to Success"]', 'D. Rovering to Success'),
(99, 'Kalung manik-manik kayu (Wood Badge) yang dikalungkan pada Pembina Pramuka lulusan kursus lanjutan berasal dari kalung pimpinan suku Afrika bernama...', '["A. Agnes Baden-Powell","B. Lord Edward Cecil","C. Dinizulu","D. Andri Bob Sunardi"]', 'C. Dinizulu'),
(99, 'Pada batu nisan makam Baden-Powell di Nyeri, Kenya, terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti rahasia...', '["A. Cerita Api Unggun (Campfire Yarns)","B. Saya telah pulang","C. Deklinasi Magnetis","D. Santo George (St. George)"]', 'B. Saya telah pulang'),
(99, 'Pasukan kavaleri pertama yang ditempati Baden-Powell saat bertugas ke India dengan pangkat Pembantu Letnan adalah...', '["A. Mafeking","B. London","C. 13th Hussars","D. Nyeri"]', 'C. 13th Hussars'),
(99, 'Buku Scouting for Boys secara struktural dibagi ke dalam 26 bab khusus yang oleh Baden-Powell disebut dengan istilah...', '["A. Boyman","B. Cerita Api Unggun (Campfire Yarns)","C. Aids to Scouting","D. Rovering to Success"]', 'B. Cerita Api Unggun (Campfire Yarns)'),
(99, 'Simpul yang paling tepat digunakan untuk menyambung dua utas tali yang ukurannya TIDAK SAMA besar dan dalam keadaan kering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Ikatan Palang (Square Lashing)","D. Simpul Mati (Reef Knot)"]', 'A. Simpul Anyam (Sheet Bend)'),
(99, 'Prinsip konservasi dalam Cerita Api Unggun ke-15 melarang pandu membunuh binatang apa pun, KECUALI...', '["A. Satyaku Kudarmakan, Darmaku Kubaktikan","B. Ing Madyo Mangun Karso","C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","D. Good Turn (Berbuat Kebaikan)"]', 'C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup'),
(99, 'Tokoh orang suci pelindung Inggris yang dijadikan simbol ksatria kaum pandu di seluruh dunia (diperingati setiap 23 April) karena keberaniannya menumpas naga adalah...', '["A. Andri Bob Sunardi","B. Santo George (St. George)","C. Sri Sultan Hamengkubuwono IX","D. Soenardjo Atmodipuro"]', 'B. Santo George (St. George)'),
(99, 'Tindakan yang Paling Tepat jika pakaian yang dikenakan tiba-tiba tersambar api menurut panduan P3K Scouting for Boys adalah...', '["A. Terjebak banjir bandang jika hujan lebat turun di hulu","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","D. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit"]', 'C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal'),
(99, 'Inspirasi utama Baden-Powell tentang pentingnya pemuda bermula dari pasukan anak-anak saat pengepungan kota Mafeking yang dipimpin oleh...', '["A. Pulau Brownsea","B. Lord Edward Cecil","C. Olympia Hall","D. Mafeking"]', 'B. Lord Edward Cecil'),
(99, 'Mendirikan tenda di dasar cekungan (lembah sempit kering) sangat dilarang oleh aturan perkemahan tingkat lanjut karena risiko...', '["A. Ponco","B. Nesting","C. Terjebak banjir bandang jika hujan lebat turun di hulu","D. Tenda Prisma"]', 'C. Terjebak banjir bandang jika hujan lebat turun di hulu'),
(99, 'Agar pasak tenda menancap kuat dan tidak mudah tercabut oleh angin, kemiringan pasak ke dalam tanah harus membentuk sudut...', '["A. Survival Kit","B. 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Tenda Prisma","D. Flysheet"]', 'B. 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(99, 'Celana berbahan Jeans/Denim dilarang keras dipakai untuk pendakian dan kemah alam bebas karena alasan medis, yaitu...', '["A. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","D. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)"]', 'B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia'),
(99, 'Penerapan prinsip "Pack it in, Pack it out" dalam manajemen sampah perkemahan berarti...', '["A. Ikhlas Bakti Bina Bangsa","B. Good Turn (Berbuat Kebaikan)","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Trisatya dan Dasadarma"]', 'C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya'),
(99, 'Simpul yang paling praktis untuk menautkan tali tenda pada pasak karena bisa ditarik ulur (dikencangkan/dikendurkan) tanpa melepas simpul adalah...', '["A. Ikatan Silang","B. Simpul Tali Tenda (Taut-line Hitch)","C. Simpul Mati (Reef Knot)","D. Simpul Delapan"]', 'B. Simpul Tali Tenda (Taut-line Hitch)'),
(99, 'Jarak minimal yang direkomendasikan untuk membangun MCK (Mandi Cuci Kakus) darurat dari sumber mata air agar tidak mencemari lingkungan adalah...', '["A. Simpul Tali Tenda (Taut-line Hitch)","B. Deklinasi Magnetis","C. 15 - 20 meter","D. Lembah atau aliran air"]', 'C. 15 - 20 meter'),
(99, 'Menurut standar telegrafi internasional, perbandingan durasi waktu antara ketukan "titik" (dot) dan "garis" (dash) dalam sandi Morse adalah...', '["A. Sandi Ular / Sandi Gergaji","B. 1 : 3","C. Simpul Tali Tenda (Taut-line Hitch)","D. Sundial (Metode Bayangan Matahari)"]', 'B. 1 : 3'),
(99, 'Isyarat prosedural (Prosign) standar internasional untuk "Attention" atau tanda memulai pesan Morse yang sah adalah...', '["A. --..-","B. .....","C. -.-.-","D. ...--"]', 'C. -.-.-'),
(99, 'Jika huruf "O" adalah (---) dan "S" adalah (...), maka huruf "C" dalam kode morse adalah...', '["A. -.-.","B. .-.-","C. .-..","D. .-.-"]', 'A. -.-.'),
(99, 'Jika memecahkan kata menggunakan "Sandi AND", hal pertama yang harus dilakukan adalah...', '["A. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. Sandi Ular / Sandi Gergaji","D. 45-60 derajat berlawanan dengan arah tarikan tali tenda"]', 'B. Menghapus semua rangkaian huruf A-N-D yang berdekatan'),
(99, 'Huruf Q dan P dalam kode morse memiliki kombinasi garis yang mengecoh. Kombinasi yang benar secara berurutan untuk Q dan P adalah...', '["A. --.- dan .--.","B. Tetanus","C. -.-.","D. Nasional"]', 'A. --.- dan .--.'),
(99, 'Isyarat bahwa pesan telah selesai seluruhnya (End of Message) dikirimkan dengan sandi...', '["A. Sandi Jam","B. AR (.-.-.)","C. Deklinasi Magnetis","D. Lembah atau aliran air"]', 'B. AR (.-.-.)'),
(99, 'Jika membaca peta topografi berskala 1:50.000 dan jarak dua titik di peta adalah 4 cm, maka jarak sebenarnya di medan adalah...', '["A. 7 kilometer","B. 2 kilometer","C. 3 kilometer","D. 7 kilometer"]', 'B. 2 kilometer'),
(99, 'Garis kontur yang tergambar menjorok ke arah tempat yang lebih tinggi (membentuk huruf V terbalik) secara topografi merupakan...', '["A. Afrika Selatan","B. Lembah atau aliran air","C. Nyeri","D. Gilwell Park"]', 'B. Lembah atau aliran air'),
(99, 'Aturan baku "Golden Rule" dalam membaca koordinat Grid (UTM) 6 angka pada peta topografi adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","D. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya"]', 'A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)'),
(99, 'Perbedaan sudut putar yang ditunjukkan antara Utara Magnetis di jarum kompas dan Utara Peta (Grid) pada selembar peta disebut...', '["A. Santo George (St. George)","B. -.-.","C. Deklinasi Magnetis","D. Lord Edward Cecil"]', 'C. Deklinasi Magnetis'),
(99, 'Alat mekanis dengan roda gigi kecil yang dijalankan menyusuri kelokan sungai di peta untuk menghitung jarak rute melengkung disebut...', '["A. Flysheet","B. Survival Kit","C. Sleeping Bag (Kantong Tidur)","D. Curvimeter"]', 'D. Curvimeter'),
(99, 'Metode navigasi siang hari tanpa kompas menggunakan bayangan tongkat tegak lurus yang memanfaatkan pergerakan semu matahari disebut...', '["A. 2 kilometer","B. Sundial (Metode Bayangan Matahari)","C. 16 - 20 tahun","D. 1 : 3"]', 'B. Sundial (Metode Bayangan Matahari)'),
(99, 'Dalam pemecahan Sandi Kotak 2, satu kotak kerangka silang dihuni oleh 3 huruf. Jika terdapat 2 titik di atas kerangka tersebut, maka itu menunjukkan huruf...', '["A. Nyeri","B. Olympia Hall","C. Ketiga","D. Pulau Brownsea"]', 'C. Ketiga'),
(99, 'Sandi Kimia mengonversi kode Morse ke huruf. Jika kode aslinya adalah "H2O" (H=konsonan, O=vokal), maka morse yang terbentuk adalah...', '["A. .--","B. .-.","C. --.","D. ..-"]', 'C. --.'),
(99, 'Sandi yang menggunakan patokan waktu dengan selisih yang konstan (misal pukul 08.00 = A, 08.05 = B, 08.10 = C) disebut...', '["A. Ketiga","B. 15 - 20 meter","C. Sandi Jam","D. Nasional"]', 'C. Sandi Jam'),
(99, 'Sandi AZ menukar huruf awal dengan huruf akhir alfabet. Jika sandinya berbunyi "K", maka huruf aslinya adalah...', '["A. 1953","B. P","C. 1 : 3","D. Tetanus"]', 'B. P'),
(99, 'Sandi yang bentuk fisiknya memanjang menyerupai gerigi atau gelombang naik turun tanpa spasi putus disebut...', '["A. 15 - 20 meter","B. UU No. 12 Tahun 2010","C. Sandi Ular / Sandi Gergaji","D. 16 - 20 tahun"]', 'C. Sandi Ular / Sandi Gergaji'),
(99, 'Dalam Sandi Koordinat tabel 5x5 dengan kata kunci "MERAH PUTIH", huruf A terletak pada titik temu kordinat...', '["A. Baris M, Kolom P","B. Deklinasi Magnetis","C. 16 - 20 tahun","D. Saya telah pulang"]', 'A. Baris M, Kolom P'),
(99, 'Tindakan Pertolongan Pertama yang BENAR pada korban kecelakaan yang mimisan (hidung berdarah) adalah...', '["A. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","B. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","D. Terjebak banjir bandang jika hujan lebat turun di hulu"]', 'C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit'),
(99, 'Rasio kompresi dada (pijat jantung) dan bantuan napas buatan pada RJP (Resusitasi Jantung Paru) untuk 1 orang penolong menurut standar medis terbaru adalah...', '["A. --.- dan .--.","B. 30 kompresi : 2 napas","C. Santo George (St. George)","D. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak"]', 'B. 30 kompresi : 2 napas'),
(99, 'Penanganan keseleo (terkilir) di lapangan paling efektif menggunakan metode RICE, yang merupakan singkatan dari...', '["A. Rest, Ice, Compression, Elevation","B. Sundial (Metode Bayangan Matahari)","C. --.- dan .--.","D. Lord Edward Cecil"]', 'A. Rest, Ice, Compression, Elevation'),
(99, 'Alasan dilarangnya mengoleskan pasta gigi, mentega, atau kecap pada luka bakar melepuh adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia"]', 'B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat'),
(99, 'Jika digigit ular berbisa di tengah hutan, penanganan paling krusial sebelum di bawa ke RS adalah...', '["A. 11 - 15 tahun","B. 16 - 20 tahun","C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening","D. 21 - 25 tahun"]', 'C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening'),
(99, 'Luka tusuk yang diakibatkan oleh benda kotor berkarat (seperti paku) sangat berisiko fatal jika tidak dicuci bersih karena membawa bakteri penyebab...', '["A. AR (.-.-.)","B. --.- dan .--.","C. Tetanus","D. 2 kilometer"]', 'C. Tetanus'),
(99, 'Pembalut elastis berwarna coklat (Elastic Bandage) sangat direkomendasikan berada di dalam kotak P3K Pramuka karena berfungsi spesifik untuk...', '["A. Pulau Brownsea","B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","C. Olympia Hall","D. London"]', 'B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak')